        fill.style.background = 'linear-gradient(90deg,#2aa4ff,#8a2be2,#ff4bd1)';
        bar.appendChild(fill);

        const info = document.createElement('div');
        info.style.marginTop = '16px';
        info.style.color = '#93a7da';
        info.style.lineHeight = '1.6';
        info.style.marginBottom = '16px';
        info.innerHTML = `
                    <div><b>Milestones:</b> seasonal Brick Bon reward track</div>
          <div><b>Next reward:</b> ${nextMilestone.threshold} bricks for ${nextMilestone.reward}</div>
        `;

        const scrollContainer = document.createElement('div');
        scrollContainer.style.flex = '1';
        scrollContainer.style.overflowY = 'auto';
        scrollContainer.style.marginBottom = '8px';
        scrollContainer.style.paddingRight = '8px';

        const list = document.createElement('div');
        list.style.display = 'grid';
        list.style.gridTemplateColumns = '1fr 1fr';
        list.style.gap = '10px';
        
        milestones.forEach((milestone) => {
            const isClaimed = claimed[milestone.threshold] === true;
            const chip = document.createElement('div');
            chip.style.padding = '10px 12px';
            chip.style.borderRadius = '12px';
            chip.style.border = '1px solid ' + (isClaimed ? '#888888' : (milestone.earned ? '#5df2c2' : '#304876'));
            chip.style.background = isClaimed ? 'rgba(136,136,136,0.08)' : (milestone.earned ? 'rgba(93,242,194,0.08)' : 'rgba(7,17,30,0.8)');
            chip.style.color = isClaimed ? '#888888' : (milestone.earned ? '#5df2c2' : '#c0d4ff');
            chip.style.fontSize = '13px';
            chip.style.display = 'flex';
            chip.style.justifyContent = 'space-between';
            chip.style.alignItems = 'center';

            const label = document.createElement('span');
            label.innerHTML = `<b>${milestone.threshold}</b><br/>${milestone.reward}`;
            label.style.flex = '1';

            if (isClaimed) {
                label.innerHTML = `<b>${milestone.threshold}</b><br/>✓ Claimed`;
            } else if (milestone.earned) {
                const claimBtn = document.createElement('button');
                claimBtn.textContent = 'Claim';
                claimBtn.style.background = '#5df2c2';
                claimBtn.style.color = '#08101d';
                claimBtn.style.border = 'none';
                claimBtn.style.borderRadius = '6px';
                claimBtn.style.padding = '4px 8px';
                claimBtn.style.cursor = 'pointer';
                claimBtn.style.fontWeight = 'bold';
                claimBtn.style.fontSize = '11px';
                claimBtn.onclick = () => {
                    claimed[milestone.threshold] = true;
                    applyBrickBonReward(milestone);
                    localStorage.setItem(claimedKey, JSON.stringify(claimed));
                    saveProgress();
                    claimBtn.textContent = '✓';
                    claimBtn.disabled = true;
                    label.innerHTML = `<b>${milestone.threshold}</b><br/>✓ Claimed`;
                    chip.style.color = '#888888';
                    chip.style.border = '1px solid #888888';
                    chip.style.background = 'rgba(136,136,136,0.08)';
                };
                chip.appendChild(label);
                chip.appendChild(claimBtn);
            } else {
                chip.appendChild(label);
            }
            
            if (isClaimed || !milestone.earned) {
                chip.appendChild(label);
            }
            
            list.appendChild(chip);
        });
        
        scrollContainer.appendChild(list);
        panel.style.position = 'relative';
        panel.appendChild(close);
        panel.appendChild(title);
        panel.appendChild(subtitle);
        panel.appendChild(bar);
        panel.appendChild(info);
        panel.appendChild(scrollContainer);
