    function openBalanceBlog() {
        const normalizeToken = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
        const typeStyle = (type) => {
            const t = String(type || 'stable').toLowerCase();
            if (t === 'buff') return { label: 'BUFF', color: '#5df2c2', bg: 'rgba(93, 242, 194, 0.2)' };
            if (t === 'nerf') return { label: 'NERF', color: '#ff8f8f', bg: 'rgba(255, 143, 143, 0.2)' };
            if (t === 'adjust') return { label: 'ADJUST', color: '#ffd166', bg: 'rgba(255, 209, 102, 0.18)' };
            if (t === 'hold') return { label: 'HOLD', color: '#a9b8cc', bg: 'rgba(169, 184, 204, 0.16)' };
            return { label: 'REWORK', color: '#c9a3ff', bg: 'rgba(201, 163, 255, 0.2)' };
        };

        const overlay = document.createElement('div');
        overlay.style.position = 'fixed';
        overlay.style.inset = '0';
        overlay.style.background = 'rgba(4, 8, 16, 0.82)';
        overlay.style.backdropFilter = 'blur(16px)';
        overlay.style.zIndex = '1200';
        overlay.style.display = 'flex';
        overlay.style.alignItems = 'center';
        overlay.style.justifyContent = 'center';
        overlay.style.fontFamily = 'sans-serif';
        overlay.style.color = '#fff';

        const panel = document.createElement('div');
        panel.style.width = 'min(860px, 92vw)';
        panel.style.height = 'min(760px, 92vh)';
        panel.style.background = 'radial-gradient(circle at 50% 0%, #152952 0%, #071022 60%, #03060c 100%)';
        panel.style.border = '1px solid rgba(130, 180, 255, 0.35)';
        panel.style.borderRadius = '24px';
        panel.style.padding = '26px';
        panel.style.boxShadow = '0 30px 100px rgba(0, 0, 0, 0.8), 0 0 50px rgba(126, 200, 255, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.1)';
        panel.style.display = 'flex';
        panel.style.flexDirection = 'column';
        panel.style.overflow = 'hidden';
        panel.style.position = 'relative';

        const close = document.createElement('button');
        close.textContent = '✕';
        close.style.position = 'absolute';
        close.style.right = '20px';
        close.style.top = '20px';
        close.style.width = '36px';
        close.style.height = '36px';
        close.style.border = '1px solid rgba(255, 255, 255, 0.15)';
        close.style.borderRadius = '12px';
        close.style.background = 'rgba(255, 255, 255, 0.08)';
        close.style.color = '#fff';
        close.style.fontWeight = 'bold';
        close.style.cursor = 'pointer';
        close.style.transition = 'all 0.2s';
        close.onmouseover = () => { close.style.background = '#ff4a4a'; close.style.color = '#000'; };
        close.onmouseout = () => { close.style.background = 'rgba(255, 255, 255, 0.08)'; close.style.color = '#fff'; };
        close.onclick = () => document.body.removeChild(overlay);

        const title = document.createElement('h1');
        title.textContent = 'Arena Forge Balance Blog';
        title.style.margin = '0 0 6px 0';
        title.style.background = 'linear-gradient(135deg, #7ec8ff 0%, #38ef7d 100%)';
        title.style.webkitBackgroundClip = 'text';
        title.style.webkitTextFillColor = 'transparent';
        title.style.letterSpacing = '0.04em';

        const subtitle = document.createElement('div');
        subtitle.textContent = `Latest Patch: ${balanceBlogEntries[0]?.tag || 'N/A'} • Live profile: ${BALANCE_PROFILE.version}`;
        subtitle.style.color = '#8dc5ff';
        subtitle.style.fontWeight = '700';
        subtitle.style.marginBottom = '16px';

        const tabs = document.createElement('div');
        tabs.style.display = 'flex';
        tabs.style.gap = '8px';
        tabs.style.marginBottom = '12px';

        const makeTabButton = (label) => {
            const btn = document.createElement('button');
            btn.textContent = label;
            btn.style.border = '1px solid #3a5e92';
            btn.style.borderRadius = '999px';
            btn.style.padding = '7px 12px';
            btn.style.background = 'rgba(17, 35, 61, 0.9)';
            btn.style.color = '#d7e8ff';
            btn.style.fontWeight = '700';
            btn.style.cursor = 'pointer';
            return btn;
        };

        const tabAll = makeTabButton('All Patches');
        const tabPinned = makeTabButton('Pinned Brawlers');
        const tabUnlocked = makeTabButton('Unlocked Brawlers');
        tabs.appendChild(tabAll);
        tabs.appendChild(tabPinned);
        tabs.appendChild(tabUnlocked);

        const scroll = document.createElement('div');
        scroll.style.flex = '1';
        scroll.style.overflowY = 'auto';
        scroll.style.paddingRight = '8px';

        const makeChangeRow = (change) => {
            const row = document.createElement('div');
            row.style.border = '1px solid #2a3f68';
            row.style.borderRadius = '10px';
            row.style.background = 'rgba(16, 30, 54, 0.7)';
            row.style.padding = '10px 12px';
            row.style.marginBottom = '8px';
            const top = document.createElement('div');
            top.style.display = 'flex';
            top.style.alignItems = 'center';
            top.style.gap = '8px';
            top.style.marginBottom = '4px';
            const style = typeStyle(change.type);
            const badge = document.createElement('span');
            badge.textContent = style.label;
            badge.style.padding = '2px 7px';
            badge.style.borderRadius = '999px';
            badge.style.background = style.bg;
            badge.style.color = style.color;
            badge.style.border = `1px solid ${style.color}`;
            badge.style.fontWeight = '800';
            badge.style.fontSize = '11px';
            const name = document.createElement('strong');
            name.textContent = `${change.brawler}`;
            name.style.color = '#e8f6ff';
            top.appendChild(badge);
            top.appendChild(name);
            if (change.area) {
                const area = document.createElement('span');
                area.textContent = change.area;
                area.style.marginLeft = 'auto';
                area.style.padding = '2px 7px';
                area.style.borderRadius = '999px';
                area.style.background = 'rgba(126, 200, 255, 0.1)';
                area.style.border = '1px solid rgba(126, 200, 255, 0.28)';
                area.style.color = '#9fd9ff';
                area.style.fontSize = '10px';
                area.style.fontWeight = '700';
                top.appendChild(area);
            }
            const nums = document.createElement('div');
            nums.textContent = change.numbers;
            nums.style.color = '#d7e8ff';
            nums.style.fontSize = '13px';
            nums.style.marginBottom = '2px';
            const why = document.createElement('div');
            why.textContent = `Why: ${change.why}`;
            why.style.color = '#9fc0eb';
            why.style.fontSize = '12px';
            row.appendChild(top);
            row.appendChild(nums);
            row.appendChild(why);
            return row;
        };

        const makeCooldownTable = (rows) => {
            const tableWrap = document.createElement('div');
            tableWrap.style.border = '1px solid #2f4d80';
            tableWrap.style.borderRadius = '10px';
            tableWrap.style.overflow = 'hidden';
            tableWrap.style.marginBottom = '10px';
            const table = document.createElement('table');
            table.style.width = '100%';
            table.style.borderCollapse = 'collapse';
            const thead = document.createElement('thead');
            const headRow = document.createElement('tr');
            for (const hTxt of ['Brawler', 'G1 CD', 'G2 CD']) {
                const th = document.createElement('th');
                th.textContent = hTxt;
                th.style.textAlign = hTxt === 'Brawler' ? 'left' : 'center';
                th.style.padding = '8px 10px';
                th.style.background = 'rgba(30, 66, 112, 0.72)';
                th.style.color = '#d9ecff';
                th.style.fontSize = '12px';
                headRow.appendChild(th);
            }
            thead.appendChild(headRow);
            table.appendChild(thead);
            const tbody = document.createElement('tbody');
            rows.forEach((rowData, idx) => {
                const tr = document.createElement('tr');
                tr.style.background = idx % 2 ? 'rgba(14, 28, 52, 0.72)' : 'rgba(10, 22, 42, 0.72)';
                const tdName = document.createElement('td');
                tdName.textContent = rowData.brawler;
                tdName.style.padding = '7px 10px';
                tdName.style.color = '#e8f6ff';
                tdName.style.fontSize = '12px';
                const tdG1 = document.createElement('td');
                tdG1.textContent = `${rowData.g1}s`;
                tdG1.style.padding = '7px 10px';
                tdG1.style.color = '#8df3cf';
                tdG1.style.textAlign = 'center';
                tdG1.style.fontSize = '12px';
                const tdG2 = document.createElement('td');
                tdG2.textContent = `${rowData.g2}s`;
                tdG2.style.padding = '7px 10px';
                tdG2.style.color = '#8de1ff';
                tdG2.style.textAlign = 'center';
                tdG2.style.fontSize = '12px';
                tr.appendChild(tdName);
                tr.appendChild(tdG1);
                tr.appendChild(tdG2);
                tbody.appendChild(tr);
            });
            table.appendChild(tbody);
            tableWrap.appendChild(table);
            return tableWrap;
        };

        const makeEntryCard = (entry, changeRows) => {
            const card = document.createElement('div');
            card.style.border = '1px solid #304876';
            card.style.borderRadius = '12px';
            card.style.padding = '14px';
            card.style.marginBottom = '10px';
            card.style.background = 'rgba(7,17,30,0.78)';

            const head = document.createElement('div');
            head.style.display = 'flex';
            head.style.alignItems = 'center';
            head.style.gap = '10px';
            head.style.marginBottom = '8px';

            const tag = document.createElement('span');
            tag.textContent = entry.tag;
            tag.style.padding = '3px 8px';
            tag.style.borderRadius = '999px';
            tag.style.background = '#2aa4ff';
            tag.style.color = '#08101d';
            tag.style.fontWeight = '800';
            tag.style.fontSize = '12px';

            const h = document.createElement('strong');
            h.textContent = entry.title;
            h.style.color = '#e8f6ff';

            const collapseBtn = document.createElement('button');
            collapseBtn.textContent = 'Collapse';
            collapseBtn.style.marginLeft = 'auto';
            collapseBtn.style.border = '1px solid #4469a1';
            collapseBtn.style.borderRadius = '999px';
            collapseBtn.style.padding = '3px 10px';
            collapseBtn.style.background = 'rgba(15, 30, 55, 0.85)';
            collapseBtn.style.color = '#d7e8ff';
            collapseBtn.style.fontSize = '11px';
            collapseBtn.style.fontWeight = '700';
            collapseBtn.style.cursor = 'pointer';

            head.appendChild(tag);
            head.appendChild(h);
            head.appendChild(collapseBtn);
            card.appendChild(head);

            const body = document.createElement('div');

            const summary = document.createElement('div');
            summary.textContent = entry.summary || '';
            summary.style.color = '#a9c5ef';
            summary.style.fontSize = '13px';
            summary.style.marginBottom = '10px';
            if (summary.textContent) body.appendChild(summary);

            if (Array.isArray(entry.gadgetCooldowns) && entry.gadgetCooldowns.length) {
                body.appendChild(makeCooldownTable(entry.gadgetCooldowns));
            }

            if (changeRows.length) {
                if (entry.grouped) {
                    const groups = new Map();
                    changeRows.forEach((change) => {
                        const section = change.section || 'Other Changes';
                        if (!groups.has(section)) groups.set(section, []);
                        groups.get(section).push(change);
                    });
                    groups.forEach((sectionChanges, section) => {
                        const sectionHead = document.createElement('div');
                        sectionHead.style.display = 'flex';
                        sectionHead.style.alignItems = 'center';
                        sectionHead.style.gap = '10px';
                        sectionHead.style.margin = '16px 0 8px';
                        sectionHead.style.padding = '8px 10px';
                        sectionHead.style.borderLeft = '4px solid #63dcff';
                        sectionHead.style.borderRadius = '7px';
                        sectionHead.style.background = 'linear-gradient(90deg, rgba(52,138,207,.22), rgba(52,138,207,.03))';
                        sectionHead.innerHTML = `<strong style="color:#eaf7ff;letter-spacing:.06em">${section.toUpperCase()}</strong><small style="color:#8ebce3">${sectionChanges.length} ${sectionChanges.length === 1 ? 'ENTRY' : 'ENTRIES'}</small>`;
                        body.appendChild(sectionHead);
                        sectionChanges.forEach((change) => body.appendChild(makeChangeRow(change)));
                    });
                } else {
                    changeRows.forEach((change) => body.appendChild(makeChangeRow(change)));
                }
            } else {
                const empty = document.createElement('div');
                empty.textContent = 'No changes for this view.';
                empty.style.color = '#9fc0eb';
                empty.style.fontSize = '12px';
                body.appendChild(empty);
            }

            collapseBtn.onclick = () => {
                const isHidden = body.style.display === 'none';
                body.style.display = isHidden ? '' : 'none';
                collapseBtn.textContent = isHidden ? 'Collapse' : 'Expand';
            };

            card.appendChild(body);
            return card;
        };

        const escapeRegex = (value) => String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const buildAliasEntries = () => {
            const idsByAlias = new Map();
            const source = (typeof brawlerData === 'object' && brawlerData) ? Object.entries(brawlerData) : [];
            for (const [id, data] of source) {
                const aliases = new Set([id, String(id).replace(/_/g, ' '), data?.name || '']);
                for (const alias of aliases) {
                    const key = normalizeToken(alias);
                    if (!key) continue;
                    if (!idsByAlias.has(key)) idsByAlias.set(key, new Set());
                    idsByAlias.get(key).add(id);
                }
            }
            const aliasEntries = [...idsByAlias.keys()]
                .sort((a, b) => b.length - a.length)
                .map((alias) => ({
                    alias,
                    regex: new RegExp(`(?:^|_)${escapeRegex(alias)}(?:_|$)`),
                    ids: [...idsByAlias.get(alias)]
                }));
            return { idsByAlias, aliasEntries };
        };

        const { idsByAlias: brawlerIdsByAlias, aliasEntries: brawlerAliasEntries } = buildAliasEntries();

        const resolveChangeBrawlerIds = (change) => {
            const ids = new Set();
            const direct = brawlerIdsByAlias.get(normalizeToken(change?.brawler || ''));
            if (direct) direct.forEach((id) => ids.add(id));

            const blob = normalizeToken(`${change?.brawler || ''} ${change?.numbers || ''} ${change?.why || ''}`);
            if (blob) {
                for (const entry of brawlerAliasEntries) {
                    if (!entry.regex.test(blob)) continue;
                    entry.ids.forEach((id) => ids.add(id));
                }
            }
            return ids;
        };

        const getPinnedIdSet = () => {
            const set = new Set();
            for (const rawId of favoriteBrawlers || []) {
                const resolved = brawlerIdsByAlias.get(normalizeToken(rawId));
                if (resolved && resolved.size) resolved.forEach((id) => set.add(id));
                else set.add(String(rawId));
            }
            return set;
        };

        const getUnlockedIdSet = () => {
            const set = new Set();
            for (const id of allBrawlers || []) {
                if (isBrawlerUnlocked(id)) set.add(id);
            }
            return set;
        };

        const getBrawlerName = (id) => brawlerData?.[id]?.name || String(id).replace(/_/g, ' ');
        const getPerBrawlerCohortNote = (change, id) => {
            const type = String(change?.type || 'rework').toLowerCase();
            if (type === 'buff') return 'Damage scalar increased via this buff cohort pass.';
            if (type === 'nerf') return 'Damage scalar tuned down via this nerf cohort pass.';
            if (type === 'rework') return 'Power curve adjusted in this rework cohort pass.';
            return String(change?.numbers || '');
        };

        const getDetailedChangesForEntry = (entry, targetIdSet) => {
            const out = [];
            for (const change of (entry.changes || [])) {
                const matchedIds = [...resolveChangeBrawlerIds(change)].filter((id) => targetIdSet.has(id));
                if (!matchedIds.length) continue;
                const directIds = brawlerIdsByAlias.get(normalizeToken(change?.brawler || '')) || new Set();
                const isGrouped = /\bcohort\b/i.test(String(change?.brawler || '')) || directIds.size > 1;
                if (!isGrouped && directIds.size === 1) {
                    out.push(change);
                    continue;
                }
                matchedIds.forEach((id) => {
                    out.push({
                        ...change,
                        brawler: getBrawlerName(id),
                        numbers: getPerBrawlerCohortNote(change, id),
                        why: `${String(change.why || '')} (${entry.tag})`
                    });
                });
            }
            return out;
        };

        const tabButtons = [tabAll, tabPinned, tabUnlocked];
        const setActiveTab = (activeBtn) => {
            tabButtons.forEach((btn) => {
                const active = btn === activeBtn;
                btn.style.background = active ? '#2aa4ff' : 'rgba(17, 35, 61, 0.9)';
                btn.style.color = active ? '#08101d' : '#d7e8ff';
                btn.style.borderColor = active ? '#2aa4ff' : '#3a5e92';
            });
        };

        const renderAll = () => {
            scroll.innerHTML = '';
            balanceBlogEntries.forEach((entry) => scroll.appendChild(makeEntryCard(entry, entry.changes || [])));
        };

        const renderPinned = () => {
            scroll.innerHTML = '';
            const pinnedIdSet = getPinnedIdSet();
            if (!pinnedIdSet.size) {
                const empty = document.createElement('div');
                empty.textContent = 'Pin brawlers on the home roster, then open this tab to see their changes.';
                empty.style.color = '#c0d4ff';
                empty.style.padding = '10px 4px';
                scroll.appendChild(empty);
                return;
            }
            let foundAny = false;
            balanceBlogEntries.forEach((entry) => {
                const filtered = getDetailedChangesForEntry(entry, pinnedIdSet);
                if (!filtered.length) return;
                foundAny = true;
                const pinnedCooldowns = (entry.gadgetCooldowns || []).filter((row) => {
                    const ids = brawlerIdsByAlias.get(normalizeToken(row?.brawler || '')) || new Set();
                    return [...ids].some((id) => pinnedIdSet.has(id));
                });
                const pinnedEntry = { ...entry, summary: `Pinned brawler full notes from ${entry.tag}.`, gadgetCooldowns: pinnedCooldowns };
                scroll.appendChild(makeEntryCard(pinnedEntry, filtered));
            });
            if (!foundAny) {
                const empty = document.createElement('div');
                empty.textContent = 'No balance changes found yet for your pinned brawlers.';
                empty.style.color = '#c0d4ff';
                empty.style.padding = '10px 4px';
                scroll.appendChild(empty);
            }
        };

        const renderUnlocked = () => {
            scroll.innerHTML = '';
            const unlockedIdSet = getUnlockedIdSet();
            if (!unlockedIdSet.size) {
                const empty = document.createElement('div');
                empty.textContent = 'No unlocked brawlers found yet.';
                empty.style.color = '#c0d4ff';
                empty.style.padding = '10px 4px';
                scroll.appendChild(empty);
                return;
            }
            let foundAny = false;
            balanceBlogEntries.forEach((entry) => {
                const filtered = getDetailedChangesForEntry(entry, unlockedIdSet);
                if (!filtered.length) return;
                foundAny = true;
                const unlockedCooldowns = (entry.gadgetCooldowns || []).filter((row) => {
                    const ids = brawlerIdsByAlias.get(normalizeToken(row?.brawler || '')) || new Set();
                    return [...ids].some((id) => unlockedIdSet.has(id));
                });
                const unlockedEntry = { ...entry, summary: `Unlocked brawler full notes from ${entry.tag}.`, gadgetCooldowns: unlockedCooldowns };
                scroll.appendChild(makeEntryCard(unlockedEntry, filtered));
            });
            if (!foundAny) {
                const empty = document.createElement('div');
                empty.textContent = 'No balance changes found yet for your unlocked brawlers.';
                empty.style.color = '#c0d4ff';
                empty.style.padding = '10px 4px';
                scroll.appendChild(empty);
            }
        };

        tabAll.onclick = () => {
            setActiveTab(tabAll);
            renderAll();
        };
        tabPinned.onclick = () => {
            setActiveTab(tabPinned);
            renderPinned();
        };
        tabUnlocked.onclick = () => {
            setActiveTab(tabUnlocked);
            renderUnlocked();
        };

        setActiveTab(tabAll);
        renderAll();

        panel.appendChild(close);
        panel.appendChild(title);
        panel.appendChild(subtitle);
        panel.appendChild(tabs);
        panel.appendChild(scroll);
        overlay.appendChild(panel);
        document.body.appendChild(overlay);
    }
        function abilityIconSvg(kind, fillColor, locked) {
                const fg = locked ? '#6f7f99' : fillColor;
                const bg = locked ? '#132036' : '#0d1728';
                if (kind === 'gadget') {
                        return `
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">
                                <rect x="4" y="4" width="72" height="72" rx="18" fill="${bg}" stroke="${fg}" stroke-width="4"/>
                                <path d="M22 32h36l7 21c2 7-5 13-11 9l-8-6H34l-8 6c-6 4-13-2-11-9z" fill="${fg}"/>
                                <path d="M28 39v12M22 45h12" stroke="${bg}" stroke-width="5" stroke-linecap="round"/>
                                <circle cx="50" cy="42" r="4" fill="${bg}"/><circle cx="57" cy="49" r="4" fill="${bg}"/>
                            </svg>`;
                }
                if (kind === 'star') {
                        return `
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">
                                <rect x="4" y="4" width="72" height="72" rx="20" fill="${bg}" stroke="${fg}" stroke-width="4"/>
                                <circle cx="40" cy="40" r="27" fill="${fg}" opacity=".25"/>
                                <path d="M40 12l8 17 19 2-14 13 4 19-17-9-17 9 4-19-14-13 19-2z" fill="${fg}"/>
                                <circle cx="40" cy="40" r="7" fill="${bg}"/>
                            </svg>`;
                }
                if (kind === 'hc') {
                        return `
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">
                                <rect x="4" y="4" width="72" height="72" rx="20" fill="${bg}" stroke="${fg}" stroke-width="4"/>
                                <path d="M40 9l27 31-27 31L13 40z" fill="${fg}" opacity=".25"/>
                                <path d="M44 13L21 43h16l-5 25 28-35H44z" fill="${fg}"/>
                            </svg>`;
                }
                if (kind === 'super') {
                        return `
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">
                                <rect x="4" y="4" width="72" height="72" rx="20" fill="${bg}" stroke="${fg}" stroke-width="4"/>
                                <path d="M20 42h40l-12 12h-8l6 16-20-24h8z" fill="${fg}"/>
                            </svg>`;
                }
                return `
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">
                                <rect x="4" y="4" width="72" height="72" rx="20" fill="${bg}" stroke="${fg}" stroke-width="4"/>
                                <path d="M29 20h22v10H29zm0 14h22v10H29zm0 14h22v10H29z" fill="${fg}"/>
                            </svg>`;
        }
        const abilityIconDataUrlCache = new Map();
        function abilityIconDataUrl(kind, fillColor, locked) {
                const key = `${kind}|${fillColor}|${locked ? 1 : 0}`;
                if (!abilityIconDataUrlCache.has(key)) {
                    abilityIconDataUrlCache.set(key, 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(abilityIconSvg(kind, fillColor, locked)));
                }
                return abilityIconDataUrlCache.get(key);
        }
        function brickFillColor(progress) {
                if (progress?.prestige) return '#2aa4ff';
                const bricks = progress?.bricks || 0;
                if (bricks >= 750) return '#ffd36e';
                if (bricks >= 500) return '#c0c7d6';
                if (bricks >= 200) return '#8b5a2b';
                return '#5d6e8e';
        }
    function getUnlocksForLevel(level) {
        return {
            gadgetUnlocked: level >= 7,
            starPowerUnlocked: level >= 9,
            hyperchargeUnlocked: level >= 11,
        };
    }
    function getSelectedProgress() {
                normalizeSelectedBrawler();
            const base = getEffectiveBrawlerProgress(selectedBrawler);
            if (!isTraining && !isDamageFillerMode && !isMirrorMode && !isRankedMatch && !isTowerTroubleMode && !isTowerDuelEvent) return base;
            return {
                ...base,
                level: 11,
                gadgetUnlocked: true,
                starPowerUnlocked: true,
                hyperchargeUnlocked: true
            };
    }
  
  function getNativeAmmoCapacity(brawlerId){
      if(brawlerId==='oil_maker')return 120;
      if(brawlerId==='minigunnin'||brawlerId==='steamer'||brawlerId==='beam')return 100;
      if(brawlerId==='bowlin_rida'||brawlerId==='boom_arang'||brawlerId==='jetpack'||brawlerId==='the_deleter')return 1;
      if(brawlerId==='demon'||brawlerId==='fastpass')return 2;
      if(brawlerId==='trampaheal')return 2;
      if(brawlerId==='rocketeer')return 4;
      return 3;
  }

  function resetPlayerAmmoForBrawler(brawlerId,includeTowerBonus=false){
      maxAmmo=getNativeAmmoCapacity(brawlerId);
      if(includeTowerBonus&&isSlopSushiMode)maxAmmo+=Math.round(getSlopEffectTotal('ammoBonus'));
      if(getCorePerk(brawlerId)==='kinetic')maxAmmo+=1;
      ammo=maxAmmo;
  }

