    function isFriendlyFirePlusActive() {
        const isFFP = (m) => m === 'friendly_fire_plus';
        return (isRankedMatch || isCustomMutatorMatch) && (isFFP(activeRankedModifier) || isFFP(activeRankedModifierSecondary) || isFFP(activeRankedModifierTertiary));
    }

    function isSuperRate90Active() {
        const isSR = (m) => m === 'super_rate_90' || m === 'super_rate_plus';
        return (isRankedMatch || isCustomMutatorMatch) && (isSR(activeRankedModifier) || isSR(activeRankedModifierSecondary) || isSR(activeRankedModifierTertiary));
    }

    function isGiantProjectilesActive() {
        const isGP = (m) => m === 'giant_projectiles' || m === 'projectiles_150' || m === 'colossal_projectiles';
        return (isRankedMatch || isCustomMutatorMatch) && (isGP(activeRankedModifier) || isGP(activeRankedModifierSecondary) || isGP(activeRankedModifierTertiary));
    }

    function applyGiantProjectilesModifier(b) {
        if (!b || b._giantProjectilesApplied) return;
        if (!isGiantProjectilesActive()) return;
        b._giantProjectilesApplied = true;
        b.hitboxMod = (b.hitboxMod || 1) * 2.5;
        if (b.radius) b.radius *= 2.5;
        if (b.ringSizeMod) b.ringSizeMod *= 2.5;
        if (b.tempoOutRadius) b.tempoOutRadius *= 2.5;
        if (b.tempoReturnRadius) b.tempoReturnRadius *= 2.5;
        b.slopSizeMultiplier = Math.max(b.slopSizeMultiplier || 1, 2.5);
    }

    // --- BOLZNSTIEN BRAWLER HELPERS ---

    function castMagnatarSuper(entity, targetX, targetY, isHyper) {
        if (!entity) return;
        const now = performance.now();
        const maxSuperRange = 660;
        const dx = targetX - entity.x;
        const dy = targetY - entity.y;
        const totalDist = Math.hypot(dx, dy);
        const ang = Math.atan2(dy, dx);
        const aimDist = Math.min(maxSuperRange, totalDist);
        let finalTargetX = entity.x + Math.cos(ang) * aimDist;
        let finalTargetY = entity.y + Math.sin(ang) * aimDist;

        // Soft magnetic auto-lock: if aiming near an enemy within 85px, snap to enemy
        const targets = entity.id === player.id ? bots : [player, ...bots];
        let lockEnemy = null;
        let lockDist = 85;
        for (const t of targets) {
            if (!t || t.hp <= 0 || t.id === entity.id || areAlliedEntities(entity, t)) continue;
            const d = Math.hypot(t.x - finalTargetX, t.y - finalTargetY);
            if (d < lockDist) {
                lockDist = d;
                lockEnemy = t;
            }
        }
        if (lockEnemy) {
            finalTargetX = lockEnemy.x;
            finalTargetY = lockEnemy.y;
        }

        const throwDist = Math.hypot(finalTargetX - entity.x, finalTargetY - entity.y);
        const speed = 860;
        const flightTime = Math.max(0.18, Math.min(1.1, throwDist / speed));
        const finalAng = Math.atan2(finalTargetY - entity.y, finalTargetX - entity.x);

        bullets.push({
            ownerBrawler: 'magnatar',
            isMagnatarBeacon: true,
            x: entity.x,
            y: entity.y,
            vx: Math.cos(finalAng) * speed,
            vy: Math.sin(finalAng) * speed,
            targetX: finalTargetX,
            targetY: finalTargetY,
            life: 0,
            maxLife: flightTime,
            damage: 650,
            ownerId: entity.id,
            hitIds: {},
            isHyper: isHyper
        });

        // HC: "super has +40% size and makes one around u that makes projectiles go around u."
        if (isHyper) {
            deployMagnatarBeacon(entity, entity.x, entity.y, null, true, true);
            spawnFloatingText(entity.x, entity.y - 45, '🧲 SINGULARITY BARRIER!', '#e056fd');
        }
    }

    function deployMagnatarBeacon(ownerEntity, x, y, attachedEntityId = null, isHyper = false, isPersonalAura = false) {
        const now = performance.now();
        const ownerId = ownerEntity ? ownerEntity.id : null;
        const sp1 = ownerEntity ? ((ownerEntity.id === player.id ? selectedStar : ownerEntity.selectedStar) === 'slow' || (ownerEntity.id === player.id ? selectedStar : ownerEntity.selectedStar) === 'sp1') : false;
        const sp2 = ownerEntity ? ((ownerEntity.id === player.id ? selectedStar : ownerEntity.selectedStar) === 'long' || (ownerEntity.id === player.id ? selectedStar : ownerEntity.selectedStar) === 'sp2') : false;

        const baseRadius = isPersonalAura ? 180 : (isHyper ? 308 : 220); // +40% size: 220 * 1.4 = 308

        const beacon = {
            id: 'magnatar_vortex_' + now + '_' + Math.floor(Math.random() * 9999),
            ownerId: ownerId,
            x: x,
            y: y,
            attachedEntityId: attachedEntityId,
            isPersonalAura: isPersonalAura,
            radius: baseRadius,
            expiresAt: now + (isPersonalAura ? 6000 : 5500),
            isHyper: isHyper,
            sp1: sp1,
            sp2: sp2,
            sp2ExtMs: 0, // SP2 nerf 2026-10-23: per-beacon total duration extension granted (cap 2000ms)
            sp2RefundPct: 0 // SP2 nerf 2026-10-23: per-beacon total Super refund granted (cap 25%)
        };

        magnatarVortices.push(beacon);

        explosions.push({
            x: x,
            y: y,
            radius: baseRadius * 0.7,
            life: 0,
            maxLife: 0.35,
            color: isHyper ? 'rgba(224, 86, 253, 0.7)' : 'rgba(0, 210, 255, 0.7)'
        });

        if (attachedEntityId) {
            const ent = getEntityById(attachedEntityId);
            if (ent) spawnFloatingText(ent.x, ent.y - 42, '🧲 MAGNET ATTACHED!', '#00d2ff');
        } else if (!isPersonalAura) {
            spawnFloatingText(x, y - 35, '🧲 POLARITY BEACON!', '#00d2ff');
        }
    }

    function executeMagnatarG1(entity) {
        if (!entity) return;
        const now = performance.now();
        const shockRadius = 180;
        const shockDmg = 900;
        const targets = entity.id === player.id ? bots : [player, ...bots];

        for (const t of targets) {
            if (!t || t.hp <= 0 || t.id === entity.id || areAlliedEntities(entity, t)) continue;
            const d = Math.hypot(t.x - entity.x, t.y - entity.y);
            if (d <= shockRadius) {
                checkHit(t, { ownerBrawler: 'magnatar', damage: shockDmg, pierce: true, ownerId: entity.id, hitIds: {} }, -1);
                applyKnockback(t, entity.x, entity.y, 320);
            }
        }

        // Deflect all nearby projectiles outwards
        for (const b of bullets) {
            if (!b || b.ownerId === entity.id) continue;
            const dist = Math.hypot(b.x - entity.x, b.y - entity.y);
            if (dist <= shockRadius + 40) {
                const repAngle = Math.atan2(b.y - entity.y, b.x - entity.x);
                const curSpd = Math.hypot(b.vx, b.vy) || 500;
                b.vx = Math.cos(repAngle) * curSpd * 1.3;
                b.vy = Math.sin(repAngle) * curSpd * 1.3;
                b.ownerId = entity.id; // Repelled projectile deflected in defense
            }
        }

        explosions.push({ x: entity.x, y: entity.y, radius: shockRadius, life: 0, maxLife: 0.3, color: 'rgba(0, 210, 255, 0.75)' });
        spawnFloatingText(entity.x, entity.y - 40, '⚡ POLARITY INVERSION! 🧲', '#00d2ff');
    }

    function executeMagnatarG2(entity) {
        if (!entity) return;
        entity.magnatarG2Armed = true;
        spawnFloatingText(entity.x, entity.y - 35, '⚡ FLUX OVERCHARGE READY! 🧲', '#00f5d4');
    }

    function scheduleBolznstienStrikes(ownerId, x, y, strikeDmg, isHyper, targetId = null) {
        const now = performance.now();
        const owner = getEntityById(ownerId);
        const sp1 = owner ? ((owner.id === player.id ? selectedStar : owner.selectedStar) === 'slow' || (owner.id === player.id ? selectedStar : owner.selectedStar) === 'sp1') : false;
        const sp2 = owner ? ((owner.id === player.id ? selectedStar : owner.selectedStar) === 'long' || (owner.id === player.id ? selectedStar : owner.selectedStar) === 'sp2') : false;
        let tempoStacks = 0;
        if (owner && sp2 && targetId != null) {
            tempoStacks = owner.bolznstienTempoTargetId === targetId
                ? Math.min(5, (owner.bolznstienTempoStacks || 1) + 1)
                : 1;
            owner.bolznstienTempoTargetId = targetId;
            owner.bolznstienTempoStacks = tempoStacks;
            owner.bolznstienTempoLastHitAt = now;
        } else if (owner && targetId != null) {
            owner.bolznstienTempoTargetId = null;
            owner.bolznstienTempoStacks = 0;
        }
        const strikeDelay = sp2 && tempoStacks > 1
            ? Math.max(160, 800 - 160 * (tempoStacks - 1))
            : 800;
        const triggerAt = now + strikeDelay;
        const finalDmg = Math.round(strikeDmg * (sp1 ? 1.25 : 1.0));
        const strikeRadius = (isHyper ? 85 : 65) * (isHyper ? 1.3 : 1.0); // 30% bigger strike during HC
        const ownerSkinId = getActiveSkinForBrawler(owner?.brawler || (owner?.id === player.id ? selectedBrawler : 'bolznstien'))?.id;

        if (isHyper) {
            // Center strike
            bolznstienPendingStrikes.push({
                ownerId, x, y, triggerAt, damage: finalDmg, radius: strikeRadius, isHyper: true, sp1, skinId: ownerSkinId
            });
            // 3 strikes in a tighter triangle around the center strike.
            for (let k = 0; k < 3; k++) {
                const strikeAngle = (k * 2 * Math.PI / 3) - Math.PI / 2;
                bolznstienPendingStrikes.push({
                    ownerId,
                    x: x + Math.cos(strikeAngle) * 100,
                    y: y + Math.sin(strikeAngle) * 100,
                    triggerAt,
                    damage: finalDmg,
                    radius: strikeRadius,
                    isHyper: true,
                    sp1,
                    skinId: ownerSkinId
                });
            }
        } else {
            bolznstienPendingStrikes.push({
                ownerId, x, y, triggerAt, damage: finalDmg, radius: strikeRadius, isHyper: false, sp1, skinId: ownerSkinId
            });
        }
    }

    function doShield(entity, amount) {
        if (!entity) return;
        if (typeof grantShield === 'function') {
            grantShield(entity, amount, 5000);
        } else {
            entity.shieldHp = (entity.shieldHp || 0) + amount;
        }
    }

    function switchCarmelaFudgeForm(entity, gadgetChoice) {
        if (!entity) return;
        const now = performance.now();
        const oldForm = entity.carmelaFudgeForm || 'carmela';
        const newForm = oldForm === 'carmela' ? 'fudge' : 'carmela';
        entity.carmelaFudgeForm = newForm;

        // Gadget 1: Sweet Recovery - heal 2000 HP
        if (gadgetChoice === 'g1') {
            doHeal(entity, 2000);
            spawnFloatingText(entity.x, entity.y - 35, '+2000 HP (Sweet Recovery)', '#2ecc71');
        } else if (gadgetChoice === 'g2') {
            // Gadget 2: Sugar Sprint - reload 1 ammo and +30% speed for 3s
            if (entity.id === player.id) {
                ammo = Math.min(maxAmmo, ammo + 1);
                ammoReloadTimer = 0;
            } else if (entity.ammo !== undefined && entity.maxAmmo !== undefined) {
                entity.ammo = Math.min(entity.maxAmmo, entity.ammo + 1);
            }
            entity.carmelaSpeedUntil = now + 3000;
            spawnFloatingText(entity.x, entity.y - 35, '+30% SPD & Reload! (Sugar Sprint)', '#f39c12');
        }

        // Star Power 2: Sweet Revenge
        const hasSp2 = (entity.id === player.id ? selectedStar : entity.selectedStar) === 'long' || (entity.id === player.id ? selectedStar : entity.selectedStar) === 'sp2';
        if (hasSp2) {
            if (newForm === 'carmela') {
                const burstDmg = 1400;
                bullets.push({
                    x: entity.x, y: entity.y, vx: 0, vy: 0,
                    owner: entity.id, ownerId: entity.id, ownerBrawler: 'carmela_fudge',
                    isCarmelaBurst: true, radius: 150, damage: burstDmg, life: 0, maxLife: 0.2
                });
                const targets = entity.id === player.id ? bots : [player, ...bots];
                for (const t of targets) {
                    if (!t || t.hp <= 0 || t.id === entity.id || areAlliedEntities(entity, t)) continue;
                    if (Math.hypot(t.x - entity.x, t.y - entity.y) <= 150) {
                        checkHit(t, { ownerBrawler: 'carmela_fudge', damage: burstDmg, pierce: true, ownerId: entity.id, hitIds: {} }, -1);
                        t.slowUntil = Math.max(t.slowUntil || 0, now + 2000);
                    }
                }
                spawnFloatingText(entity.x, entity.y - 45, '🍬 CARAMEL BURST! 🍬', '#d35400');
            } else if (newForm === 'fudge') {
                chocolatePuddles.push({
                    x: entity.x, y: entity.y, radius: 120, ownerId: entity.id, expiresAt: now + 4000, slowAmount: 0.40
                });
                spawnFloatingText(entity.x, entity.y - 45, '🍫 CHOCOLATE PUDDLE! 🍫', '#5d4037');
            }
        }

        spawnFloatingText(entity.x, entity.y - 20, newForm === 'fudge' ? '🍫 FUDGE STANCE! 🍫' : '🍬 CARMELA STANCE! 🍬', newForm === 'fudge' ? '#795548' : '#e67e22');
    }

    function castCarmelaSuper(entity, isHyper) {
        if (!entity) return;
        const now = performance.now();
        entity.carmelaSuperHandsLeft = 4;
        entity.carmelaSuperUntil = now + 5000;
        entity.carmelaSuperIsHyper = isHyper;
        spawnFloatingText(entity.x, entity.y - 40, isHyper ? '🍬 HYPER QUAD SLAM! 🍬' : '🍬 QUAD SLAM! 🍬', isHyper ? '#e056fd' : '#e67e22');
    }

    function castFudgeSuper(entity, isHyper, targetX, targetY) {
        if (!entity) return;
        const now = performance.now();
        const ang = Math.atan2(targetY - entity.y, targetX - entity.x);
        bullets.push({
            ownerBrawler: 'carmela_fudge',
            isFudgeSuperBoulder: true,
            x: entity.x + Math.cos(ang) * (entity.radius + 16),
            y: entity.y + Math.sin(ang) * (entity.radius + 16),
            vx: Math.cos(ang) * 850,
            vy: Math.sin(ang) * 850,
            life: 0,
            maxLife: 0.9,
            damage: 1800,
            ownerId: entity.id,
            hitIds: {},
            isHyper: isHyper
        });
        spawnFloatingText(entity.x, entity.y - 40, isHyper ? '🍫 COCOA CATACLYSM! 🍫' : '🍫 ULTIMATE SHELL! 🍫', isHyper ? '#e056fd' : '#795548');
    }

    function drawChocolateShell(targetCtx, target) {
        if (!target || !target.inChocolateShell) return;
        const r = (target.radius || 16) * 1.45;
        targetCtx.save();
        targetCtx.translate(target.x, target.y);
        const grad = targetCtx.createRadialGradient(0, -r * 0.3, r * 0.2, 0, 0, r);
        grad.addColorStop(0, '#8d6e63');
        grad.addColorStop(0.6, '#4e342e');
        grad.addColorStop(1, '#271710');
        targetCtx.fillStyle = grad;
        targetCtx.strokeStyle = '#d7ccc8';
        targetCtx.lineWidth = 3;
        targetCtx.beginPath();
        targetCtx.ellipse(0, 0, r, r * 1.15, 0, 0, Math.PI * 2);
        targetCtx.fill();
        targetCtx.stroke();

        targetCtx.strokeStyle = '#3e2723';
        targetCtx.lineWidth = 2;
        targetCtx.beginPath();
        targetCtx.moveTo(-r * 0.5, -r * 0.4);
        targetCtx.lineTo(-r * 0.2, 0);
        targetCtx.lineTo(-r * 0.4, r * 0.5);
        targetCtx.moveTo(r * 0.3, -r * 0.5);
        targetCtx.lineTo(r * 0.1, -r * 0.1);
        targetCtx.lineTo(r * 0.35, r * 0.4);
        targetCtx.stroke();

        const hpPct = clamp((target.chocolateShellHp || 0) / (target.chocolateShellMaxHp || 3500), 0, 1);
        targetCtx.fillStyle = 'rgba(0, 0, 0, 0.6)';
        targetCtx.fillRect(-r, -r - 14, r * 2, 6);
        targetCtx.fillStyle = '#ffb300';
        targetCtx.fillRect(-r, -r - 14, r * 2 * hpPct, 6);
        targetCtx.strokeStyle = '#fff';
        targetCtx.lineWidth = 1;
        targetCtx.strokeRect(-r, -r - 14, r * 2, 6);
        targetCtx.restore();
    }

    
    // ==========================================
    // ⌫ THE DELETER (EXOTIC CONTROLLER / ASSASSIN)
    // ==========================================
    const DELETER_REWRITE_SPEED = 325;
    const DELETER_REWRITE_RANGE = 760;
    const DELETER_CLONE_DURATION_MS = 8000;
    let nextDeleterVolleyId = 1;

    function ensureDeleterState(entity) {
        if (!entity) return;
        if (!Number.isFinite(entity.deleterClonesUntil)) entity.deleterClonesUntil = 0;
        if (!Number.isFinite(entity.deleterCloneCount)) entity.deleterCloneCount = 0;
        if (!Number.isFinite(entity.deleterCloneDamageMult)) entity.deleterCloneDamageMult = .30;
        if (typeof entity.deleterHardRedirectArmed !== 'boolean') entity.deleterHardRedirectArmed = false;
    }

    function getActiveDeleterMaster(owner) {
        if (!owner) return null;
        return bullets.find(projectile => projectile && projectile.ownerId === owner.id &&
            projectile.isDeleterRewrite && projectile.deleterMaster && projectile.life < projectile.maxLife) || null;
    }

    function getDeleterCloneOffsets(owner, now = performance.now()) {
        ensureDeleterState(owner);
        if (!owner || owner.hp <= 0 || now >= owner.deleterClonesUntil) return [];
        const count = Math.max(0, Math.min(3, Math.floor(owner.deleterCloneCount || 0)));
        const facing = Number.isFinite(owner.visualAimAngle) ? owner.visualAimAngle : (owner.dir || 0);
        const sideX = -Math.sin(facing), sideY = Math.cos(facing);
        const backX = -Math.cos(facing), backY = -Math.sin(facing);
        if (count === 2) return [
            { x: sideX * 62 + backX * 10, y: sideY * 62 + backY * 10 },
            { x: -sideX * 62 + backX * 10, y: -sideY * 62 + backY * 10 }
        ];
        if (count === 3) return [
            { x: sideX * 66, y: sideY * 66 },
            { x: -sideX * 66, y: -sideY * 66 },
            { x: backX * 70, y: backY * 70 }
        ];
        return [];
    }

    function createDeleterRewriteProjectile(owner, startX, startY, angle, damage, volleyId, options = {}) {
        const speed = DELETER_REWRITE_SPEED;
        const projectile = {
            ownerBrawler: 'the_deleter', ownerId: owner.id,
            isDeleterRewrite: true, deleterMaster: !!options.master,
            deleterCloneShot: !!options.clone, deleterVolleyId: volleyId,
            deleterExecuteThreshold: options.master ? (options.hyper ? .35 : .20) : 0,
            x: startX, y: startY, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
            life: 0, maxLife: DELETER_REWRITE_RANGE / speed, damage,
            pierce: false, hitIds: {}, hitboxMod: options.clone ? 1.1 : 1.55,
            hyperVisual: !!options.hyper, deleterTargetAngle: angle,
            deleterTrailAt: 0
        };
        bullets.push(projectile);
        return projectile;
    }

    function launchDeleterRewrite(owner, angle, isBot, hyper) {
        ensureDeleterState(owner);
        const level = owner.id === player.id ? getSelectedBrawlerLevel() : (owner.level || owner.powerLevel || 11);
        const damage = getScaledStats('the_deleter', level).dmg;
        const volleyId = `${owner.id}:delete:${nextDeleterVolleyId++}`;
        const muzzle = (owner.radius || 16) + 11;
        createDeleterRewriteProjectile(owner, owner.x + Math.cos(angle) * muzzle, owner.y + Math.sin(angle) * muzzle,
            angle, damage, volleyId, { master: true, hyper });
        const cloneMult = hyper ? .50 : (getEntityStarChoice(owner) === 'long' ? .35 : .30);
        for (const offset of getDeleterCloneOffsets(owner)) {
            createDeleterRewriteProjectile(owner, owner.x + offset.x, owner.y + offset.y,
                angle, Math.round(damage * cloneMult), volleyId, { clone: true, hyper });
        }
        explosions.push({x:owner.x+Math.cos(angle)*muzzle,y:owner.y+Math.sin(angle)*muzzle,radius:30,life:0,maxLife:.18,color:hyper?'rgba(217,82,255,.72)':'rgba(255,49,95,.66)',fxKind:'deleterMuzzle'});
    }

    function redirectDeleterVolley(owner, master, targetX, targetY, isBot) {
        if (!owner || !master || master.deleterRedirected) return false;
        master.deleterRedirected = true;
        const desired = Math.atan2(targetY - master.y, targetX - master.x);
        const hard = !!owner.deleterHardRedirectArmed;
        const accelerate = getEntityStarChoice(owner) === 'slow';
        for (const projectile of bullets) {
            if (!projectile?.isDeleterRewrite || projectile.ownerId !== owner.id || projectile.deleterVolleyId !== master.deleterVolleyId) continue;
            projectile.deleterTargetAngle = desired;
            projectile.deleterTurnRate = hard ? 99 : 3.4;
            if (hard) {
                const speed = Math.hypot(projectile.vx, projectile.vy) || DELETER_REWRITE_SPEED;
                projectile.vx = Math.cos(desired) * speed;
                projectile.vy = Math.sin(desired) * speed;
                projectile.maxLife += Math.max(.10, (projectile.maxLife - projectile.life) * .20);
            }
            if (accelerate && !projectile.deleterTrackingAccelerated) {
                projectile.vx *= 1.20; projectile.vy *= 1.20;
                projectile.deleterTrackingAccelerated = true;
            }
            projectile.deleterRedirectFlashUntil = performance.now() + 220;
        }
        if (hard) {
            owner.deleterHardRedirectArmed = false;
            if (!isBot && owner.id === player.id) {
                gadgetArmed = false;
                gadgetCooldownUntil = performance.now() + getGadgetCooldownMsForBrawler('the_deleter','g1');
                setPlayerGadgetCooldownUntil(gadgetCooldownUntil,'g1');
                updateGadgetButton();
            }
        }
        explosions.push({x:master.x,y:master.y,radius:38,life:0,maxLife:.18,color:hard?'rgba(255,214,81,.78)':'rgba(255,71,114,.64)',fxKind:'deleterRedirect'});
        return true;
    }

    function castDeleterSuper(owner, hyper) {
        if (!owner) return;
        const now = performance.now();
        ensureDeleterState(owner);
        owner.deleterClonesUntil = now + DELETER_CLONE_DURATION_MS;
        owner.deleterCloneCount = hyper ? 3 : 2;
        owner.deleterCloneDamageMult = hyper ? .50 : (getEntityStarChoice(owner) === 'long' ? .35 : .30);
        explosions.push({x:owner.x,y:owner.y,radius:hyper?155:120,life:0,maxLife:.46,color:hyper?'rgba(111,16,151,.86)':'rgba(255,49,95,.68)',legendary:true,fxKind:'deleterSuper'});
        spawnFloatingText(owner.x, owner.y - 45, hyper ? 'TOTAL ERASURE ×3' : 'DELETE FROM EXISTENCE ×2', hyper ? '#ed9cff' : '#ff7595');
    }

    function updateDeleterSystems(entity, now = performance.now()) {
        if (!entity) return;
        if (entity.hp <= 0) {
            entity.deleterClonesUntil = 0;
            entity.deleterCloneCount = 0;
            entity.deleterHardRedirectArmed = false;
            return;
        }
        if (entity.id === player.id) {
            if (entity.deleterWaitingForRelease && !mouse.down && !mobileInput.aimHeld && !mobileInput.attackActive) {
                entity.deleterWaitingForRelease = false;
                entity.deleterRedirectReady = true;
            }
        }
    }

    function castBolznstienSuper(entity, isHyper) {
        if (!entity) return;
        const now = performance.now();
        // Super duration: 4s normal, 6s in Hypercharge
        const duration = isHyper ? 6000 : 4000;
        entity.bolznstienSuperUntil = now + duration;
        entity.bolznstienSuperIsHyper = isHyper;
        entity.bolznstienLastSuperTick = 0;
        const skin = getActiveSkinForBrawler(entity.brawler || (entity.id === player.id ? selectedBrawler : 'bolznstien'));
        if (skin?.id === 'headless-bolznstien') {
            spawnFloatingText(entity.x, entity.y - 40, isHyper ? '🎃 SPECTRAL REAPING! 🎃' : '🎃 PUMPKIN SHOCKWAVE! 🎃', '#ff7700');
        } else {
            spawnFloatingText(entity.x, entity.y - 40, isHyper ? '⚡ FRANKEN-OVERLOAD! 🧟' : '⚡ ELECTRIC EYES! ⚡', isHyper ? '#e056fd' : '#00f5d4');
        }
        if (entity === player) updateSignatureButton();
    }

    function executeBolznstienG1(entity) {
        if (!entity) return;
        const now = performance.now();
        // G1: Instant Discharge - Immediately detonate all pending strikes for this owner with +30% damage, plus a defensive shock
        let detonatedCount = 0;
        for (let i = bolznstienPendingStrikes.length - 1; i >= 0; i--) {
            const s = bolznstienPendingStrikes[i];
            if (s.ownerId === entity.id) {
                s.triggerAt = 0;
                s.damage = Math.round(s.damage * 1.30); // +30% damage
                detonatedCount++;
            }
        }
        // Defensive shock around Bolznstien
        const shockDmg = 800;
        const targets = entity.id === player.id ? bots : [player, ...bots];
        for (const t of targets) {
            if (!t || t.hp <= 0 || t.id === entity.id || areAlliedEntities(entity, t)) continue;
            const d = Math.hypot(t.x - entity.x, t.y - entity.y);
            if (d <= 140) {
                checkHit(t, { ownerBrawler: 'bolznstien', damage: shockDmg, pierce: true, ownerId: entity.id, hitIds: {} }, -1);
                applyKnockback(t, entity.x, entity.y, 220);
            }
        }
        const skinId = getActiveSkinForBrawler(entity.brawler || (entity.id === player.id ? selectedBrawler : 'bolznstien'))?.id;
        const isHeadless = skinId === 'headless-bolznstien';
        explosions.push({ x: entity.x, y: entity.y, radius: 140, life: 0, maxLife: 0.25, color: isHeadless ? 'rgba(46, 204, 113, 0.75)' : 'rgba(0, 245, 212, 0.65)', skinId });
        spawnFloatingText(entity.x, entity.y - 35, isHeadless ? '🎃 SPECTRAL DISCHARGE!' : '⚡ INSTANT DISCHARGE!', isHeadless ? '#2ecc71' : '#00f5d4');
    }

    function executeBolznstienG2(entity) {
        if (!entity) return;
        const now = performance.now();
        // G2: Conductive Surge - +30% movement speed for 4s and leaves shocking electric floor trails
        const skinId = getActiveSkinForBrawler(entity.brawler || (entity.id === player.id ? selectedBrawler : 'bolznstien'))?.id;
        const isHeadless = skinId === 'headless-bolznstien';
        entity.bolznstienSpeedUntil = now + 4000;
        spawnFloatingText(entity.x, entity.y - 35, isHeadless ? '🎃 SPECTRAL SURGE! (+30% SPD)' : '⚡ CONDUCTIVE SURGE! (+30% SPD)', isHeadless ? '#2ecc71' : '#ffd166');
    }

    let nextBadBatId = 1;

    function fireBadBatAttack(fromEntity, ang, isHyper) {
        if (!fromEntity) return;
        const now = performance.now();
        const level = fromEntity.id === player.id ? getSelectedBrawlerLevel() : (fromEntity.level || 11);
        const stats = getScaledStats('badbat', level);
        const dmg = stats.dmg || 1400;
        const speed = 920;
        const range = 440;
        const isG1 = (fromEntity.badbatG1Until || 0) > now || !!fromEntity.badbatG1Active;
        if (isG1) {
            fromEntity.badbatG1Active = false;
        }

        // +50% Main Attack Size (42 base / 84 with G1)
        const baseRadius = isG1 ? 84 : 42;
        const maxLife = range / speed;

        bullets.push({
            ownerBrawler: 'badbat',
            isBadBatWave: true,
            x: fromEntity.x + Math.cos(ang) * (fromEntity.radius + 14),
            y: fromEntity.y + Math.sin(ang) * (fromEntity.radius + 14),
            vx: Math.cos(ang) * speed,
            vy: Math.sin(ang) * speed,
            life: 0,
            maxLife: maxLife,
            damage: dmg,
            pierce: true,
            pierceWalls: false,
            ownerId: fromEntity.id,
            hitIds: {},
            isHyper: !!isHyper,
            g1Active: isG1,
            baseRadius: baseRadius,
            radius: baseRadius,
            hitboxMod: baseRadius / 4,
            ang: ang
        });

        fromEntity.visualAttackAt = now;
        fromEntity.attackKick = 1.0;
        fromEntity.visualAimAngle = ang;
    }

    function spawnBadBatOrbitingBats(owner, count = 1, targetId = null, isSuper = false, isHyper = false) {
        if (!owner || owner.hp <= 0) return;
        const totalAlive = badbatSwarm.filter(b => b.ownerId === owner.id && b.hp > 0);
        const MAX_BADBAT_TOTAL = 6;
        const toSpawn = Math.min(count, Math.max(0, MAX_BADBAT_TOTAL - totalAlive.length));
        if (toSpawn <= 0) return;

        const now = performance.now();
        const BADBAT_ROAM_RANGE = 176; // 40% range around owner (440 range * 0.40)
        for (let i = 0; i < toSpawn; i++) {
            const spawnAng = (Math.PI * 2 / toSpawn) * i + Math.random() * 0.5;
            const spawnDist = 28 + Math.random() * (BADBAT_ROAM_RANGE - 36);
            const assignedTargetId = targetId || owner.badbatMarkedTargetId || null;
            badbatSwarm.push({
                id: nextBadBatId++,
                ownerId: owner.id,
                team: owner.team || (owner.id === player.id ? 'player' : 'enemy'),
                x: owner.x + Math.cos(spawnAng) * Math.min(spawnDist, 40),
                y: owner.y + Math.sin(spawnAng) * Math.min(spawnDist, 40),
                vx: Math.cos(spawnAng) * 200,
                vy: Math.sin(spawnAng) * 200,
                hp: 560,
                maxHp: 560,
                shield: 0,
                radius: 14,
                isPet: true,
                isBadBatMinion: true,
                state: assignedTargetId ? 'pre_dash' : 'roam',
                roamOffsetX: Math.cos(spawnAng) * spawnDist,
                roamOffsetY: Math.sin(spawnAng) * spawnDist,
                nextRoamRetarget: now + 800 + Math.random() * 1200,
                targetId: assignedTargetId,
                dashTargetId: assignedTargetId,
                preDashTarget: assignedTargetId,
                preDashUntil: assignedTargetId ? (now + 240) : 0,
                markPulse: 0,
                hitCount: 0,
                maxHits: Infinity,
                isSuperBat: !!isSuper,
                isHyperBat: !!isHyper,
                lastStrikeTime: now - 1500, // Attack immediately if enemies are in range
                spawnedAt: now
            });
        }
    }

    function castBadBatSuper(entity, isHyper) {
        if (!entity || entity.hp <= 0) return;
        const now = performance.now();
        const totalAlive = badbatSwarm.filter(b => b.ownerId === entity.id && b.hp > 0);
        const MAX_BADBAT_TOTAL = 6;
        const available = Math.max(0, MAX_BADBAT_TOTAL - totalAlive.length);
        const batCount = Math.min(isHyper ? 6 : 4, available);
        if (batCount <= 0) return;

        const BADBAT_ROAM_RANGE = 176; // 40% range around owner (440 range * 0.40)
        const enemies = (entity.id === player.id ? bots : [player, ...bots])
            .filter(t => t && t.hp > 0 && t.id !== entity.id && !areAlliedEntities(entity, t) && !t.isDummy);

        for (let i = 0; i < batCount; i++) {
            const assignedTarget = enemies.length > 0 ? enemies[i % enemies.length] : null;
            const ringAng = (Math.PI * 2 / batCount) * i + Math.random() * 0.4;
            const roamDist = 32 + Math.random() * (BADBAT_ROAM_RANGE - 40);
            const bat = {
                id: nextBadBatId++,
                ownerId: entity.id,
                team: entity.team || (entity.id === player.id ? 'player' : 'enemy'),
                x: entity.x + Math.cos(ringAng) * (entity.radius + 18),
                y: entity.y + Math.sin(ringAng) * (entity.radius + 18),
                vx: Math.cos(ringAng) * 450,
                vy: Math.sin(ringAng) * 450,
                hp: 560,
                maxHp: 560,
                shield: 0,
                radius: 14,
                isPet: true,
                isBadBatMinion: true,
                state: assignedTarget ? 'pre_dash' : 'roam',
                roamOffsetX: Math.cos(ringAng) * roamDist,
                roamOffsetY: Math.sin(ringAng) * roamDist,
                nextRoamRetarget: now + 900 + Math.random() * 1200,
                targetId: assignedTarget ? assignedTarget.id : null,
                dashTargetId: assignedTarget ? assignedTarget.id : null,
                preDashTarget: assignedTarget ? assignedTarget.id : null,
                preDashUntil: assignedTarget ? (now + 220) : 0,
                markPulse: 0,
                hitCount: 0,
                maxHits: Infinity,
                isSuperBat: true,
                isHyperBat: !!isHyper,
                lastStrikeTime: now - 1500, // Autonomous instant engagement
                spawnedAt: now
            };
            badbatSwarm.push(bat);
        }

        entity.visualSuperAt = now;
        explosions.push({
            ownerId: entity.id,
            damage: 0,
            isParticle: true,
            isVisualOnly: true,
            x: entity.x,
            y: entity.y,
            radius: 90,
            life: 0,
            maxLife: 0.35,
            color: isHyper ? 'rgba(224, 86, 253, 0.85)' : 'rgba(123, 44, 191, 0.8)'
        });
        spawnFloatingText(entity.x, entity.y - 40, isHyper ? '🦇 NOCTURNAL SWARM! 🦇' : '🦇 BAT COLONY ERUPTION!', isHyper ? '#e056fd' : '#9d4edd');
    }

    function executeFeathersG1(entity) {
        if (!entity || entity.hp <= 0) return;
        const now = performance.now();
        let ang;
        if (entity.id === player.id) { const wm = getMouseWorld(); ang = Math.atan2(wm.y - entity.y, wm.x - entity.x); }
        else { const t = [player, ...bots].find((e) => e && e.id === entity.lastTargetId) || player; ang = Math.atan2((t ? t.y : entity.y) - entity.y, (t ? t.x : entity.x) - entity.x); }
        const startX = entity.x, startY = entity.y;
        entity.x = clamp(entity.x + Math.cos(ang) * 210, entity.radius, WORLD_W - entity.radius);
        entity.y = clamp(entity.y + Math.sin(ang) * 210, entity.radius, WORLD_H - entity.radius);
        entity.feathersHasteUntil = now + 1500;
        spawnFeathersWind(startX, startY, Math.cos(ang), Math.sin(ang), entity.id);
        spawnFeathersWind(entity.x, entity.y, Math.cos(ang), Math.sin(ang), entity.id);
        explosions.push({ x: entity.x, y: entity.y, radius: 60, life: 0, maxLife: .22, color: 'rgba(127,231,255,.55)' });
        spawnFloatingText(entity.x, entity.y - 32, '🪶 TAILWIND RUSH', '#7fe7ff');
    }

    function executeFeathersG2(entity) {
        if (!entity || entity.hp <= 0) return;
        entity.slowUntil = 0;
        AOEDamage(entity.x, entity.y, 185, 350, entity.id, false);
        for (const e of [player, ...bots]) {
            if (!e || e.hp <= 0 || e.id === entity.id) continue;
            if (areAlliedEntities(entity, e)) continue;
            if (Math.hypot(e.x - entity.x, e.y - entity.y) <= 185) applyKnockback(e, entity.x, entity.y, 175);
        }
        explosions.push({ x: entity.x, y: entity.y, radius: 185, life: 0, maxLife: .25, color: 'rgba(191,239,255,.5)' });
        spawnFloatingText(entity.x, entity.y - 32, '💨 GUST BURST', '#bfefff');
    }

    function executeBadBatG1(entity) {
        if (!entity || entity.hp <= 0) return;
        const now = performance.now();
        entity.badbatG1Until = now + 2000;
        entity.badbatG1Active = true;
        explosions.push({
            x: entity.x,
            y: entity.y,
            radius: 70,
            life: 0,
            maxLife: 0.25,
            color: 'rgba(157, 78, 221, 0.65)'
        });
        spawnFloatingText(entity.x, entity.y - 35, '🦇 WIDE RESONATOR (+100% WIDTH)', '#c77dff');
    }

    function executeBadBatG2(entity) {
        if (!entity || entity.hp <= 0) return;
        let shieldedCount = 0;
        for (const bat of badbatSwarm) {
            if (bat.ownerId === entity.id && bat.hp > 0) {
                bat.shield = (bat.shield || 0) + 1000;
                shieldedCount++;
            }
        }
        explosions.push({
            x: entity.x,
            y: entity.y,
            radius: 80,
            life: 0,
            maxLife: 0.28,
            color: 'rgba(0, 245, 212, 0.65)'
        });
        spawnFloatingText(entity.x, entity.y - 35, `🦇 COLONY WARD (+1000 SHIELD${shieldedCount > 0 ? ` ×${shieldedCount}` : ''})`, '#00f5d4');
    }

    function updateBadBatSwarm(dt, now) {
        const MAX_BADBAT_TOTAL = 6;
        const BADBAT_ROAM_RANGE = 176; // 40% range of BadBat (440 range * 0.40)

        // 1. Strict Total Cap — max 6 active bats per owner at any time
        const ownerCounts = {};
        for (let i = badbatSwarm.length - 1; i >= 0; i--) {
            const b = badbatSwarm[i];
            if (!b || b.hp <= 0) continue;
            ownerCounts[b.ownerId] = (ownerCounts[b.ownerId] || 0) + 1;
            if (ownerCounts[b.ownerId] > MAX_BADBAT_TOTAL) {
                b.hp = 0;
            }
        }

        // 2. Update Shield Orbs flying back to owners
        for (let oi = badbatShieldOrbs.length - 1; oi >= 0; oi--) {
            const orb = badbatShieldOrbs[oi];
            if (!orb) { badbatShieldOrbs.splice(oi, 1); continue; }
            const owner = getEntityById(orb.ownerId);
            if (!owner || owner.hp <= 0) {
                badbatShieldOrbs.splice(oi, 1);
                continue;
            }
            const dx = owner.x - orb.x;
            const dy = owner.y - orb.y;
            const dist = Math.hypot(dx, dy);
            if (dist <= (owner.radius || 14) + 16 || dist < 20) {
                doShield(owner, orb.amount || 300);
                spawnFloatingText(owner.x, owner.y - 44, `+${orb.amount || 300} SHIELD 🛡️`, '#e056fd');
                badbatShieldOrbs.splice(oi, 1);
                continue;
            }
            const spd = 720;
            orb.x += (dx / dist) * spd * dt;
            orb.y += (dy / dist) * spd * dt;
        }

        // 3. Update Bat Minions
        for (let bi = badbatSwarm.length - 1; bi >= 0; bi--) {
            const bat = badbatSwarm[bi];
            if (!bat || bat.hp <= 0) {
                if (bat) {
                    explosions.push({
                        x: bat.x, y: bat.y,
                        radius: bat.isSuperBat ? 36 : 24,
                        life: 0, maxLife: 0.22,
                        color: bat.isSuperBat ? 'rgba(196,78,255,0.75)' : 'rgba(123,44,191,0.7)'
                    });
                }
                badbatSwarm.splice(bi, 1);
                continue;
            }

            const owner = getEntityById(bat.ownerId);
            if (!owner || owner.hp <= 0) {
                bat.hp = 0;
                badbatSwarm.splice(bi, 1);
                continue;
            }

            // --- Animation ticks (Ground Walking & Dashing) ---
            const isDashing = bat.state === 'dash_to';
            const isWalking = bat.state === 'roam' || bat.state === 'orbit' || bat.state === 'pre_dash';
            bat.wingFlap = ((bat.wingFlap || 0) + dt * (isDashing ? 22 : (isWalking ? 8 : 12))) % (Math.PI * 2);
            bat.legPhase = ((bat.legPhase || 0) + dt * (isWalking ? 10 : 3)) % (Math.PI * 2);
            bat.hopZ = isWalking ? Math.abs(Math.sin(bat.legPhase)) * 6 : (isDashing ? 2 : 8);

            const hasSp1 = (owner.id === player.id ? selectedStar : owner.selectedStar) === 'slow' || (owner.id === player.id ? selectedStar : owner.selectedStar) === 'sp1';
            const hasSp2 = (owner.id === player.id ? selectedStar : owner.selectedStar) === 'long' || (owner.id === player.id ? selectedStar : owner.selectedStar) === 'sp2';
            const strikeInterval = hasSp2 ? 900 : 1400;

            // --- Autonomous Target Resolution & Aggro ---
            let target = null;
            const enemies = (owner.id === player.id ? bots : [player, ...bots])
                .filter(t => t && t.hp > 0 && t.id !== owner.id && !areAlliedEntities(owner, t) && !t.isDummy);

            // 1. Prioritize marked enemies
            const markedEnemy = enemies.find(e => (e.badbatMarkedUntil || 0) > now && Math.hypot(e.x - owner.x, e.y - owner.y) <= 720);
            if (markedEnemy) {
                target = markedEnemy;
                bat.targetId = target.id;
            } else if (bat.targetId) {
                const current = getEntityById(bat.targetId);
                if (current && current.hp > 0 && !areAlliedEntities(owner, current) && Math.hypot(current.x - owner.x, current.y - owner.y) <= 720) {
                    target = current;
                }
            }

            // 2. Otherwise acquire closest hostile enemy in aggro range (Autonomous Aggro)
            if (!target && enemies.length > 0) {
                let nearest = null, nearDist = 650;
                for (const e of enemies) {
                    const d = Math.hypot(e.x - bat.x, e.y - bat.y);
                    if (d < nearDist) { nearDist = d; nearest = e; }
                }
                if (nearest) { target = nearest; bat.targetId = target.id; }
            }

            // ---- State machine ----
            if (bat.state === 'roam' || bat.state === 'orbit') {
                bat.state = 'roam';
                if (bat.roamOffsetX === undefined || now >= (bat.nextRoamRetarget || 0)) {
                    const rAng = Math.random() * Math.PI * 2;
                    const rDist = 24 + Math.random() * (BADBAT_ROAM_RANGE - 32);
                    bat.roamOffsetX = Math.cos(rAng) * rDist;
                    bat.roamOffsetY = Math.sin(rAng) * rDist;
                    bat.nextRoamRetarget = now + 900 + Math.random() * 1400;
                }

                const distFromOwner = Math.hypot(bat.x - owner.x, bat.y - owner.y);
                let destX = owner.x + bat.roamOffsetX;
                let destY = owner.y + bat.roamOffsetY;
                let walkSpeed = 240;

                // Leash enforcement: if bat drifted outside roam radius, pull straight back towards owner vigorously
                if (distFromOwner > BADBAT_ROAM_RANGE) {
                    destX = owner.x;
                    destY = owner.y;
                    walkSpeed = Math.min(880, 360 + (distFromOwner - BADBAT_ROAM_RANGE) * 4.5);
                }

                const toDestX = destX - bat.x;
                const toDestY = destY - bat.y;
                const toDestDist = Math.hypot(toDestX, toDestY);

                if (toDestDist > 4) {
                    bat.facing = Math.atan2(toDestY, toDestX);
                    bat.x += (toDestX / toDestDist) * walkSpeed * dt;
                    bat.y += (toDestY / toDestDist) * walkSpeed * dt;
                } else {
                    bat.nextRoamRetarget = now + 300 + Math.random() * 600;
                }

                // Check if target is ready to be locked and attacked autonomously
                // (Only initiate pre_dash if bat is comfortably within tether leash of owner)
                if (distFromOwner <= BADBAT_ROAM_RANGE + 30 && target && target.hp > 0 && !areAlliedEntities(owner, target)) {
                    const distToTarget = Math.hypot(target.x - bat.x, target.y - bat.y);
                    const distTargetToOwner = Math.hypot(target.x - owner.x, target.y - owner.y);
                    if (distToTarget <= 600 && distTargetToOwner <= 650 && (now - (bat.lastStrikeTime || 0)) >= strikeInterval) {
                        // Mark target and enter pre-dash telegraph!
                        bat.state = 'pre_dash';
                        bat.preDashTarget = target.id;
                        bat.dashTargetId  = target.id;
                        bat.preDashUntil  = now + 280;
                        bat.markPulse     = 0;
                        target.badbatLockonUntil = now + 350;
                        target.badbatLockonFromBat = bat.id;
                    }
                }

            } else if (bat.state === 'pre_dash') {
                // Pre-dash telegraph: bat points straight at target, laser line locks on
                bat.markPulse = ((bat.markPulse || 0) + dt * 20) % (Math.PI * 2);
                const curTgt = (bat.dashTargetId ? getEntityById(bat.dashTargetId) : null) || target;
                if (curTgt && curTgt.hp > 0 && !areAlliedEntities(owner, curTgt)) {
                    bat.facing = Math.atan2(curTgt.y - bat.y, curTgt.x - bat.x);
                    curTgt.badbatLockonUntil = now + 150;
                    curTgt.badbatLockonFromBat = bat.id;
                } else {
                    bat.state = 'dash_back';
                    bat.dashBackStartTime = now;
                    continue;
                }
                if (now >= bat.preDashUntil) {
                    bat.state = 'dash_to';
                    bat.dashStartTime = now;
                }

            } else if (bat.state === 'dash_to') {
                const curTarget = (bat.dashTargetId ? getEntityById(bat.dashTargetId) : null) || target;
                if (!curTarget || curTarget.hp <= 0 || areAlliedEntities(owner, curTarget)) {
                    bat.state = 'dash_back';
                    bat.dashBackStartTime = now;
                    continue;
                }
                const dx = curTarget.x - bat.x;
                const dy = curTarget.y - bat.y;
                const dist = Math.hypot(dx, dy);
                const dashSpeed = 960;
                if (dist > 1) bat.facing = Math.atan2(dy, dx);

                // Ghost trails
                if (!bat.ghostTrails) bat.ghostTrails = [];
                bat.ghostTrails.push({ x: bat.x, y: bat.y, facing: bat.facing, alpha: 0.75, isSpr: bat.isSuperBat });
                if (bat.ghostTrails.length > 6) bat.ghostTrails.shift();

                const hitThreshold = (curTarget.radius || 16) + bat.radius + 18;
                const stepDist = dashSpeed * dt;

                // High-precision reliable hit detection (handles fast movement & near proximity)
                if (dist <= hitThreshold || dist <= stepDist + 12) {
                    // Snap to target contact
                    if (dist > 1) {
                        bat.x = curTarget.x - (dx / dist) * ((curTarget.radius || 14) + 6);
                        bat.y = curTarget.y - (dy / dist) * ((curTarget.radius || 14) + 6);
                    }

                    checkHit(curTarget, {
                        ownerBrawler: 'badbat',
                        damage: 300,
                        pierce: true,
                        ownerId: owner.id,
                        hitIds: {},
                        isBadBatStrike: true
                    }, -1);

                    explosions.push({
                        ownerId: owner.id,
                        damage: 0,
                        isParticle: true,
                        isVisualOnly: true,
                        x: curTarget.x, y: curTarget.y,
                        radius: 36, life: 0, maxLife: 0.2,
                        color: bat.isHyperBat ? 'rgba(224,86,253,0.95)' : 'rgba(157,78,221,0.9)'
                    });

                    if (hasSp1) {
                        doHeal(owner, 150);
                        spawnFloatingText(owner.x, owner.y - 32, '+150 LIFESTEAL 🩸', '#2ed573');
                    }

                    if (bat.isHyperBat || isEntityHyperchargedNow(owner, now)) {
                        badbatShieldOrbs.push({ x: curTarget.x, y: curTarget.y, ownerId: owner.id, amount: 300 });
                    }

                    bat.hitCount = (bat.hitCount || 0) + 1;
                    bat.lastStrikeTime = now;
                    bat.dashBackStartTime = now;
                    bat.state = 'dash_back';
                } else {
                    bat.x += (dx / dist) * stepDist;
                    bat.y += (dy / dist) * stepDist;

                    // Dash safety timeout to prevent getting lost if target teleported
                    if (now - (bat.dashStartTime || now) > 1100) {
                        bat.dashBackStartTime = now;
                        bat.state = 'dash_back';
                    }
                }

            } else if (bat.state === 'dash_back') {
                const dx = owner.x - bat.x;
                const dy = owner.y - bat.y;
                const dist = Math.hypot(dx, dy);
                if (dist > 2) bat.facing = Math.atan2(dy, dx);

                const returnSpeed = 880;
                const returnStep = returnSpeed * dt;

                // Return close to owner before entering roam mode again
                if (dist <= 64 || dist <= returnStep + 8 || (now - (bat.dashBackStartTime || now)) > 1400) {
                    bat.state = 'roam';
                    bat.nextRoamRetarget = 0;
                    bat.roamOffsetX = 0;
                    bat.roamOffsetY = 0;
                } else {
                    bat.x += (dx / dist) * returnStep;
                    bat.y += (dy / dist) * returnStep;
                }
            }

            // ---- Damageability against EVERYTHING HOSTILE (Enemy Bullets, Hostile Explosions) ----
            // 1. Bullet collisions with bat minion (BadBat & allies cannot damage own bats)
            for (let bIndex = bullets.length - 1; bIndex >= 0; bIndex--) {
                const b = bullets[bIndex];
                if (!b || b.ownerId === owner.id || b.isBadBatWave || areAlliedEntities(getEntityById(b.ownerId), owner)) continue;
                if (Math.hypot(b.x - bat.x, b.y - bat.y) <= (b.radius || 12) + bat.radius) {
                    const bulletDmg = b.damage || 400;
                    if (bat.shield > 0) {
                        if (bat.shield >= bulletDmg) {
                            bat.shield -= bulletDmg;
                        } else {
                            bat.hp -= (bulletDmg - bat.shield);
                            bat.shield = 0;
                        }
                    } else {
                        bat.hp -= bulletDmg;
                    }
                    spawnFloatingText(bat.x, bat.y - 20, `-${bulletDmg}`, '#ff4757');
                    if (!b.pierce) bullets.splice(bIndex, 1);
                    if (bat.hp <= 0) break;
                }
            }

            // 2. Active Hostile Explosions / Area Damage against bat minion (BadBat & allies cannot damage own bats)
            if (bat.hp > 0) {
                for (const exp of explosions) {
                    if (!exp || exp.life > 0.05 || !exp.radius) continue;
                    if (exp.ownerId && (exp.ownerId === owner.id || areAlliedEntities(getEntityById(exp.ownerId), owner))) continue;
                    if (!exp.damage || exp.damage <= 0 || exp.isParticle || exp.isVisualOnly) continue;
                    if (Math.hypot(exp.x - bat.x, exp.y - bat.y) <= exp.radius + bat.radius) {
                        const expDmg = exp.damage;
                        if (bat.shield > 0) {
                            if (bat.shield >= expDmg) {
                                bat.shield -= expDmg;
                            } else {
                                bat.hp -= (expDmg - bat.shield);
                                bat.shield = 0;
                            }
                        } else {
                            bat.hp -= expDmg;
                        }
                        spawnFloatingText(bat.x, bat.y - 20, `-${expDmg}`, '#ff4757');
                        if (bat.hp <= 0) break;
                    }
                }
            }
        }
    }

    function renderBadBatSwarm(ctx) {
        const now = performance.now();

        // 1. Draw shield orbs
        for (const orb of badbatShieldOrbs) {
            if (!orb) continue;
            ctx.save();
            ctx.globalAlpha = orb.alpha !== undefined ? orb.alpha : 0.9;
            ctx.shadowColor = '#e056fd';
            ctx.shadowBlur = 12;
            ctx.beginPath();
            ctx.arc(orb.x, orb.y, orb.radius || 9, 0, Math.PI * 2);
            const gOrb = ctx.createRadialGradient(orb.x, orb.y, 0, orb.x, orb.y, orb.radius || 9);
            gOrb.addColorStop(0, '#ffffff');
            gOrb.addColorStop(0.4, '#e056fd');
            gOrb.addColorStop(1, 'rgba(120,0,200,0)');
            ctx.fillStyle = gOrb;
            ctx.fill();
            ctx.restore();
        }

        // 2. Draw pre-dash telegraph laser lines to targets (High-contrast, animated tracking lock-on)
        for (const bat of badbatSwarm) {
            if (!bat || bat.hp <= 0 || bat.state !== 'pre_dash') continue;
            const target = bat.dashTargetId ? getEntityById(bat.dashTargetId) : null;
            if (!target || target.hp <= 0) continue;

            ctx.save();
            const mp = bat.markPulse || 0;
            const lineAng = Math.atan2(target.y - bat.y, target.x - bat.x);
            const lineDist = Math.hypot(target.x - bat.x, target.y - bat.y);

            // Glowing Outer Laser Line
            ctx.shadowColor = '#ff0055';
            ctx.shadowBlur = 12;
            ctx.strokeStyle = `rgba(255, 23, 68, ${0.75 + Math.sin(mp * 2.5) * 0.25})`;
            ctx.lineWidth = 3.5;
            ctx.setLineDash([10, 6]);
            ctx.lineDashOffset = -now * 0.08;
            ctx.beginPath();
            ctx.moveTo(bat.x, bat.y);
            ctx.lineTo(target.x, target.y);
            ctx.stroke();

            // Inner Crisp Core Laser Line
            ctx.shadowBlur = 0;
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1.2;
            ctx.setLineDash([6, 10]);
            ctx.lineDashOffset = -now * 0.08;
            ctx.beginPath();
            ctx.moveTo(bat.x, bat.y);
            ctx.lineTo(target.x, target.y);
            ctx.stroke();

            // Animated pulsing energy beads rushing towards target
            ctx.setLineDash([]);
            const beadProgress = ((now * 0.003) % 1);
            const beadX = bat.x + (target.x - bat.x) * beadProgress;
            const beadY = bat.y + (target.y - bat.y) * beadProgress;
            ctx.fillStyle = '#ffffff';
            ctx.shadowColor = '#ff2a55';
            ctx.shadowBlur = 8;
            ctx.beginPath();
            ctx.arc(beadX, beadY, 3.5, 0, Math.PI * 2);
            ctx.fill();

            // Lock-on Target Crosshair & Telegraph Reticle
            ctx.translate(target.x, target.y);
            const lockPulse = 1 + Math.sin(mp * 3) * 0.12;
            ctx.scale(lockPulse, lockPulse);

            // Pulsing target aura ring
            ctx.strokeStyle = 'rgba(255, 42, 85, 0.9)';
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.arc(0, 0, (target.radius || 16) + 12, 0, Math.PI * 2);
            ctx.stroke();

            // 4 rotating reticle corner brackets
            for (let k = 0; k < 4; k++) {
                const a = (Math.PI / 2) * k + now * 0.0035;
                const r1 = (target.radius || 16) + 8;
                const r2 = (target.radius || 16) + 18;
                ctx.beginPath();
                ctx.moveTo(Math.cos(a) * r1, Math.sin(a) * r1);
                ctx.lineTo(Math.cos(a) * r2, Math.sin(a) * r2);
                ctx.stroke();
            }

            // High-contrast Warning Lock-on Pill Badge
            const pillW = 82;
            const pillH = 16;
            const pillY = -(target.radius || 16) - 24;
            ctx.fillStyle = 'rgba(8, 0, 12, 0.9)';
            ctx.beginPath();
            ctx.roundRect(-pillW / 2, pillY - pillH / 2, pillW, pillH, 4);
            ctx.fill();
            ctx.strokeStyle = '#ff2a55';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            ctx.font = '900 9.5px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = '#ff3366';
            ctx.shadowColor = '#000000';
            ctx.shadowBlur = 3;
            ctx.fillText('⚠️ BAT LOCK-ON', 0, pillY);
            ctx.restore();
        }

        // 3. Draw bat minions
        for (const bat of badbatSwarm) {
            if (!bat || bat.hp <= 0) continue;
            const bx = bat.x, by = bat.y;
            const br = bat.radius || 14;
            const facing = bat.facing || 0;
            const wingFlap = bat.wingFlap || 0;
            const legPhase = bat.legPhase || 0;
            const hopZ = bat.hopZ || 0;
            const isSpr = !!bat.isSuperBat;

            // Ghost trails during dash
            if (bat.ghostTrails && bat.ghostTrails.length > 0) {
                for (let ti = 0; ti < bat.ghostTrails.length; ti++) {
                    const gt = bat.ghostTrails[ti];
                    const gAlpha = (ti + 1) / (bat.ghostTrails.length + 1) * 0.4;
                    ctx.save();
                    ctx.globalAlpha = gAlpha;
                    ctx.translate(gt.x, gt.y);
                    ctx.rotate(gt.facing);
                    ctx.fillStyle = gt.isSpr ? '#a855f7' : '#7c3aed';
                    ctx.beginPath();
                    ctx.arc(0, 0, br * 0.85, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.restore();
                }
            }

            // Ground shadow
            ctx.save();
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath();
            ctx.ellipse(bx, by + br * 0.8, br * 0.95, br * 0.45, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();

            // Bat body container
            ctx.save();
            ctx.translate(bx, by - hopZ);
            ctx.rotate(facing);

            // ── Wings ──
            const waveY = Math.sin(wingFlap) * br * 1.25;
            // Left wing
            ctx.beginPath();
            ctx.moveTo(-br * 0.8, 0);
            ctx.quadraticCurveTo(-br * 2.5, -br * 0.7 + waveY, -br * 0.2, -br * 0.7);
            ctx.quadraticCurveTo(-br * 1.5, -br * 0.2, -br * 0.8, 0);
            ctx.closePath();
            ctx.fillStyle = isSpr ? '#8b24d6' : '#5b189a';
            ctx.shadowColor = isSpr ? '#d946ef' : '#9d4edd';
            ctx.shadowBlur = isSpr ? 14 : 6;
            ctx.fill();
            // Right wing
            ctx.beginPath();
            ctx.moveTo(br * 0.8, 0);
            ctx.quadraticCurveTo(br * 2.5, -br * 0.7 + waveY, br * 0.2, -br * 0.7);
            ctx.quadraticCurveTo(br * 1.5, -br * 0.2, br * 0.8, 0);
            ctx.closePath();
            ctx.fill();
            ctx.shadowBlur = 0;

            // ── Body ──
            ctx.beginPath();
            ctx.arc(0, 0, br, 0, Math.PI * 2);
            const bodyGrad = ctx.createRadialGradient(-br * 0.25, -br * 0.25, 0, 0, 0, br);
            bodyGrad.addColorStop(0, isSpr ? '#8a30d0' : '#3a1460');
            bodyGrad.addColorStop(1, isSpr ? '#250042' : '#120520');
            ctx.fillStyle = bodyGrad;
            ctx.shadowColor = isSpr ? '#c77dff' : '#9d4edd';
            ctx.shadowBlur = isSpr ? 18 : 8;
            ctx.fill();
            ctx.strokeStyle = isSpr ? '#e0aaff' : '#a855f7';
            ctx.lineWidth = isSpr ? 2.4 : 1.6;
            ctx.stroke();
            ctx.shadowBlur = 0;

            // ── Pointy Bat Ears ──
            ctx.beginPath();
            ctx.moveTo(-br * 0.45, -br * 0.7);
            ctx.lineTo(-br * 0.75, -br * 1.45);
            ctx.lineTo(-br * 0.15, -br * 0.85);
            ctx.closePath();
            ctx.fillStyle = isSpr ? '#c084fc' : '#7e22ce';
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(br * 0.45, -br * 0.7);
            ctx.lineTo(br * 0.75, -br * 1.45);
            ctx.lineTo(br * 0.15, -br * 0.85);
            ctx.closePath();
            ctx.fill();

            // ── Eyes (Flash intense crimson/yellow during pre_dash telegraph) ──
            const isPreDash = bat.state === 'pre_dash';
            ctx.shadowColor = isPreDash ? '#ff0055' : '#facc15';
            ctx.shadowBlur = isPreDash ? 14 : 7;
            ctx.fillStyle = isPreDash ? '#ff3366' : '#fde047';
            ctx.beginPath();
            ctx.arc(-br * 0.3, -br * 0.15, 2.8, 0, Math.PI * 2);
            ctx.arc(br * 0.3, -br * 0.15, 2.8, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
            // Pupils
            ctx.fillStyle = isPreDash ? '#ffffff' : '#1e102d';
            ctx.beginPath();
            ctx.arc(-br * 0.3, -br * 0.1, 1.3, 0, Math.PI * 2);
            ctx.arc(br * 0.3, -br * 0.1, 1.3, 0, Math.PI * 2);
            ctx.fill();

            // ── Vampire Fangs ──
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.moveTo(-br * 0.2, br * 0.35);
            ctx.lineTo(-br * 0.1, br * 0.65);
            ctx.lineTo(0, br * 0.35);
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(0, br * 0.35);
            ctx.lineTo(br * 0.1, br * 0.65);
            ctx.lineTo(br * 0.2, br * 0.35);
            ctx.fill();

            // ── Walking Paws / Legs ──
            if (bat.state === 'roam' || bat.state === 'orbit' || bat.state === 'pre_dash') {
                const legL = br * 0.65;
                const stepA = Math.sin(legPhase) * 0.5;
                ctx.strokeStyle = isSpr ? '#c084fc' : '#9333ea';
                ctx.lineWidth = 2.2;
                ctx.lineCap = 'round';
                // Left leg
                ctx.save();
                ctx.rotate(-0.35 + stepA);
                ctx.beginPath();
                ctx.moveTo(-br * 0.35, br * 0.5);
                ctx.lineTo(-br * 0.35 - Math.sin(0.3 - stepA) * legL, br * 0.5 + Math.cos(0.3 - stepA) * legL);
                ctx.stroke();
                ctx.restore();
                // Right leg
                ctx.save();
                ctx.rotate(0.35 - stepA);
                ctx.beginPath();
                ctx.moveTo(br * 0.35, br * 0.5);
                ctx.lineTo(br * 0.35 + Math.sin(0.3 + stepA) * legL, br * 0.5 + Math.cos(0.3 + stepA) * legL);
                ctx.stroke();
                ctx.restore();
            }

            ctx.restore();

            // ── High-Visibility Overhead Health Bar (Crystal Clear, Stable, High-Contrast) ──
            ctx.save();
            const curHp = Math.max(0, Math.ceil(bat.hp || 0));
            const maxHp = bat.maxHp || 560;
            const hpPct = clamp(curHp / maxHp, 0, 1);
            const barW = 46;
            const barH = 9;
            const barX = bx - barW / 2;
            const barY = by - br - 18; // Stable anchor above bat

            // Dark backdrop with outer shadow
            ctx.shadowColor = 'rgba(0, 0, 0, 0.65)';
            ctx.shadowBlur = 4;
            ctx.fillStyle = 'rgba(5, 8, 18, 0.95)';
            ctx.beginPath();
            ctx.roundRect(barX - 1.5, barY - 1.5, barW + 3, barH + 3, 4);
            ctx.fill();
            ctx.shadowBlur = 0;

            // Health gradient fill
            let hpColor1, hpColor2;
            if (hpPct > 0.5) {
                hpColor1 = '#10b981'; hpColor2 = '#34d399';
            } else if (hpPct > 0.25) {
                hpColor1 = '#f59e0b'; hpColor2 = '#fbbf24';
            } else {
                hpColor1 = '#ef4444'; hpColor2 = '#f87171';
            }

            if (hpPct > 0) {
                const fillW = Math.max(5, barW * hpPct);
                const hpGrad = ctx.createLinearGradient(barX, barY, barX + fillW, barY);
                hpGrad.addColorStop(0, hpColor1);
                hpGrad.addColorStop(1, hpColor2);
                ctx.fillStyle = hpGrad;
                ctx.beginPath();
                ctx.roundRect(barX, barY, fillW, barH, 3);
                ctx.fill();

                // Subtle top highlight sheen
                ctx.fillStyle = 'rgba(255, 255, 255, 0.28)';
                ctx.beginPath();
                ctx.roundRect(barX, barY, fillW, barH * 0.45, [3, 3, 0, 0]);
                ctx.fill();
            }

            // High-contrast outer stroke
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)';
            ctx.lineWidth = 1.2;
            ctx.beginPath();
            ctx.roundRect(barX, barY, barW, barH, 3);
            ctx.stroke();

            // Crisp White HP Number with Heavy Outline
            ctx.font = '900 8.5px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.lineWidth = 2.4;
            ctx.strokeStyle = '#000000';
            ctx.strokeText(`${curHp}`, bx, barY + barH / 2 + 0.5);
            ctx.fillStyle = '#ffffff';
            ctx.fillText(`${curHp}`, bx, barY + barH / 2 + 0.5);

            // Super bat star badge
            if (isSpr) {
                ctx.font = 'bold 9px sans-serif';
                ctx.textAlign = 'right';
                ctx.fillStyle = '#fbbf24';
                ctx.shadowColor = '#000000';
                ctx.shadowBlur = 3;
                ctx.fillText('★', barX - 3, barY + barH / 2 + 0.5);
            }

            // Shield Bar (if overshield is active)
            if (bat.shield > 0) {
                const shY = barY - 8;
                const shPct = clamp(bat.shield / (bat.maxShield || 1000), 0, 1);
                ctx.fillStyle = 'rgba(5, 8, 18, 0.95)';
                ctx.beginPath();
                ctx.roundRect(barX - 1.5, shY - 1.5, barW + 3, 7, 3);
                ctx.fill();

                const shGrad = ctx.createLinearGradient(barX, shY, barX + barW * shPct, shY);
                shGrad.addColorStop(0, '#06b6d4');
                shGrad.addColorStop(1, '#38bdf8');
                ctx.fillStyle = shGrad;
                ctx.beginPath();
                ctx.roundRect(barX, shY, Math.max(4, barW * shPct), 5, 2);
                ctx.fill();

                ctx.strokeStyle = '#000000';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.roundRect(barX, shY, barW, 5, 2);
                ctx.stroke();

                ctx.font = '900 7.5px sans-serif';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.lineWidth = 2.2;
                ctx.strokeStyle = '#000000';
                ctx.strokeText(`${Math.ceil(bat.shield)}`, bx, shY + 2.5);
                ctx.fillStyle = '#e0f2fe';
                ctx.fillText(`${Math.ceil(bat.shield)}`, bx, shY + 2.5);
            }
            ctx.restore();
        }
    }

