  function getBeastBossDifficultyIndex() {
      const idx = Number(playerData?.beastBossDifficulty || 0);
      return Math.max(0, Math.min(BEAST_BOSS_DIFFICULTIES.length - 1, Number.isFinite(idx) ? idx : 0));
  }

  function getBeastBossDifficultyName(index) {
      const i = Math.max(0, Math.min(BEAST_BOSS_DIFFICULTIES.length - 1, Number(index) || 0));
      return BEAST_BOSS_DIFFICULTIES[i];
  }

  function getBeastBossDifficultySettings(index) {
      const i = Math.max(0, Math.min(4, Number(index) || 0));
      return [
          { hpMult: 15.5, speedMult: 0.9, crystalCd: 5200, superCd: 7600, roar: false, pounce: false, summon: false, frenzy: false, damageMult: 1.0 },
          { hpMult: 18.0, speedMult: 0.95, crystalCd: 4500, superCd: 7000, roar: true, pounce: false, summon: false, frenzy: false, damageMult: 1.1 },
          { hpMult: 21.0, speedMult: 1.0, crystalCd: 3900, superCd: 6200, roar: true, pounce: true, summon: false, frenzy: false, damageMult: 1.2 },
          { hpMult: 24.0, speedMult: 1.05, crystalCd: 3400, superCd: 5600, roar: true, pounce: true, summon: true, frenzy: false, damageMult: 1.5 },
          { hpMult: 28.0, speedMult: 1.12, crystalCd: 2800, superCd: 5000, roar: true, pounce: true, summon: true, frenzy: true, damageMult: 2.0 },
      ][i];
  }
  let hasHandledGameOver = false;
  let playerTeam = [];
  let botTeam = [];
  let playerScore = 0;
  let botScore = 0;
  let duelRoundState = 'playing'; 
  let duelTransitionTime = 0;
  let savedPlayerSuper = 0, savedPlayerHyper = 0, savedBotSuper = 0, savedBotHyper = 0;
    let soloTrialWave = 0;
    let soloTrialPending = false;
  const SOLO_TRIAL_MAX_WAVES = 11;
