  function syncAbilityInputs() {
      normalizeSelectedBrawler();
      const prog = getSelectedProgress();
      const gadgetUnlocked = isTraining || !!prog.gadgetUnlocked;
      const spUnlocked = isTraining || !!prog.starPowerUnlocked;

      if (gadgetUnlocked) {
          selectedGadget = prog.selectedGadget || selectedGadget || 'g1';
          syncSelectedGadgetCooldown();
      }

      if (gadgetInputs) {
          gadgetInputs.forEach(inp => {
              inp.disabled = !gadgetUnlocked;
              inp.checked = inp.value === selectedGadget;
          });
      }

      if (!spUnlocked) {
          selectedStar = 'none';
      } else {
          selectedStar = prog.selectedStar || selectedStar;
          if (selectedStar !== 'slow' && selectedStar !== 'long') selectedStar = 'slow';
      }

      starInputs.forEach(inp => {
          inp.disabled = !spUnlocked;
          inp.checked = spUnlocked && inp.value === selectedStar;
      });
      if (selectedBrawler === 'rager' || selectedBrawler === 'bolznstien' || selectedBrawler === 'magnatar' || selectedBrawler === 'carmela_fudge') {
          if (!selectedGadget) selectedGadget = 'g1';
          if (!selectedStar || selectedStar === 'none') selectedStar = 'slow';
      }
  }


  function openAllTappers() {
      const regCount = playerData.starrDrops || 0;
      const superCount = playerData.superTapperCount || 0;
      const hyperCount = playerData.hyperTapperCount || 0;
      const totalTappers = regCount + superCount + hyperCount;
      if (totalTappers <= 0) return;

      let totalCoins = 0;
      let totalGems = 0;
      let totalSouls = 0;
      let totalCorePieces = 0;
      const unlockedSkins = [];
      const unlockedHypers = [];

      const regRarities = [
          { name: 'Rare', coinMin: 15, coinMax: 30 },
          { name: 'Super Rare', coinMin: 40, coinMax: 80 },
          { name: 'Epic', coinMin: 100, coinMax: 200 },
          { name: 'Mythic', coinMin: 250, coinMax: 400 },
          { name: 'Legendary', coinMin: 500, coinMax: 1000 },
          { name: 'Ultra', coinMin: 1500, coinMax: 2500 }
      ];

      for (let i = 0; i < regCount; i++) {
          let rarityScore = 0;
          for (let t = 0; t < 4; t++) {
              if (Math.random() < 0.48) rarityScore++;
          }
          rarityScore = Math.min(rarityScore, regRarities.length - 1);
          const rInfo = regRarities[rarityScore];
          const coins = Math.floor(Math.random() * (rInfo.coinMax - rInfo.coinMin + 1)) + rInfo.coinMin;
          const gems = Math.max(1, Math.floor(coins / 400));
          const souls = rollSoulReward(8, 18);
          totalCoins += coins;
          totalGems += gems;
          totalSouls += souls;
          if (Math.random() < 0.15) totalCorePieces += 2 + Math.floor(Math.random() * 9);
          const bulkSkin = rollTapperSkinDrop(0.02);
          if (bulkSkin && !bulkSkin.fallback) unlockedSkins.push(bulkSkin.name);
      }

      const superRarities = [
          { name: 'Rare', coinMin: 50, coinMax: 80 },
          { name: 'Super Rare', coinMin: 100, coinMax: 160 },
          { name: 'Epic', coinMin: 200, coinMax: 350 },
          { name: 'Mythic', coinMin: 400, coinMax: 700 },
          { name: 'Legendary', coinMin: 800, coinMax: 1500 },
          { name: 'Ultra', coinMin: 2000, coinMax: 3500 }
      ];

      for (let i = 0; i < superCount; i++) {
          const splits = Math.floor(Math.random() * 7) + 2;
          let superCoins = 0;
          for (let s = 0; s < splits; s++) {
              const r = Math.random() * 100;
              let choice;
              if (r < 3) choice = superRarities[5];
              else if (r < 12) choice = superRarities[4];
              else if (r < 30) choice = superRarities[3];
              else if (r < 55) choice = superRarities[2];
              else if (r < 80) choice = superRarities[1];
              else choice = superRarities[0];
              superCoins += Math.floor(Math.random() * (choice.coinMax - choice.coinMin + 1)) + choice.coinMin;
          }
          const gems = Math.max(2, Math.floor(superCoins / 250));
          const souls = rollSoulReward(20, 40);
          totalCoins += superCoins;
          totalGems += gems;
          totalSouls += souls;
          for (let s2 = 0; s2 < splits; s2++) if (Math.random() < 0.15) totalCorePieces += 2 + Math.floor(Math.random() * 4);
          const bulkSkin2 = rollTapperSkinDrop(0.04);
          if (bulkSkin2 && !bulkSkin2.fallback) unlockedSkins.push(bulkSkin2.name);

      }

      for (let i = 0; i < hyperCount; i++) {
          const isHyper = Math.random() < 0.65;
          const souls = rollSoulReward(45, 80);
          totalSouls += souls;

          if (isHyper) {
              const lockedHyperBrawlers = allBrawlers.filter((bid) => {
                  const prog = getOrCreateProgress(bid);
                  const isDisabled = (brawlerData && brawlerData[bid] && brawlerData[bid].disabled) || disabledBrawlers.has(bid);
                  return !isDisabled && !prog.hyperchargeUnlocked;
              });
              if (lockedHyperBrawlers.length > 0) {
                  const chosenId = lockedHyperBrawlers[Math.floor(Math.random() * lockedHyperBrawlers.length)];
                  const chosenProg = getOrCreateProgress(chosenId);
                  chosenProg.hyperchargeUnlocked = true;
                  totalGems += 8;
                  const chosenName = (brawlerData[chosenId] && brawlerData[chosenId].name) || chosenId;
                  unlockedHypers.push(chosenName);
              } else {
                  totalCorePieces += 60;
              }
          } else {
              totalCorePieces += 60;
          }
      }

      playerData.starrDrops = 0;
      playerData.superTapperCount = 0;
      playerData.hyperTapperCount = 0;
      playerData.coins += totalCoins;
      playerData.gems += totalGems;
      addSouls(totalSouls);
      if (totalCorePieces) addCorePieces(totalCorePieces);
      saveProgress();

      if (selectedBrawler && typeof updateHyperButton === 'function') updateHyperButton();
      if (typeof refreshBrawlerList === 'function') refreshBrawlerList();
      if (typeof refreshHomeUI === 'function') refreshHomeUI();

      const overlay = document.createElement('div');
      overlay.style.position = 'fixed'; overlay.style.inset = '0';
      overlay.style.background = 'rgba(4, 9, 22, 0.96)'; overlay.style.zIndex = '2500';
      overlay.style.display = 'flex'; overlay.style.flexDirection = 'column';
      overlay.style.alignItems = 'center'; overlay.style.justifyContent = 'center';
      overlay.style.color = '#fff'; overlay.style.fontFamily = 'sans-serif';
      overlay.style.padding = '24px';
      
      const title = document.createElement('h1');
      title.textContent = '🌟 BULK OPEN COMPLETE 🌟';
      title.style.color = '#ffd166';
      title.style.textShadow = '0 0 24px rgba(255, 209, 102, 0.4)';
      overlay.appendChild(title);

      const subtitle = document.createElement('p');
      subtitle.textContent = `Opened: ${regCount} Tappers, ${superCount} Supers, ${hyperCount} Surge Tappers`;
      subtitle.style.color = '#89aed2';
      overlay.appendChild(subtitle);

      const results = document.createElement('div');
      results.style.background = 'rgba(255,255,255,0.03)';
      results.style.border = '1px solid rgba(255,255,255,0.08)';
      results.style.borderRadius = '16px';
      results.style.padding = '20px 32px';
      results.style.marginTop = '16px';
      results.style.fontSize = '18px';
      results.style.lineHeight = '1.8';
      results.style.textAlign = 'center';

      let hypersText = '';
      if (unlockedHypers.length > 0) {
          hypersText = `<div style="color: #d282ff; font-weight: bold; margin-top: 10px;">⚡ HYPERCHARGES UNLOCKED:<br>${unlockedHypers.join(', ')}</div>`;
      }

      results.innerHTML = `
          <div style="font-size: 24px; font-weight: bold; color: #5df2c2; margin-bottom: 8px;">TOTAL REWARDS</div>
          <div style="color: #ffd166; font-weight: 800;">🪙 +${totalCoins.toLocaleString()} COINS</div>
          <div style="color: #6ee7ff; font-weight: 800;">💎 +${totalGems.toLocaleString()} GEMS</div>
          <div style="color: #b983ff; font-weight: 800;">🧪 +${totalSouls.toLocaleString()} SOULS</div>
          ${totalCorePieces ? `<div style="color: #59f2d6; font-weight: 800;">💠 +${totalCorePieces.toLocaleString()} CORE PIECES</div>` : ''}
          ${unlockedSkins.length ? `<div style="color: #ff9ff3; font-weight: 800;">🎁 SKIN DROPS: ${unlockedSkins.join(', ')}</div>` : ''}
          ${hypersText}
      `;
      overlay.appendChild(results);

      const closeBtn = document.createElement('button');
      closeBtn.textContent = 'AWESOME!';
      closeBtn.style.marginTop = '24px';
      closeBtn.style.padding = '12px 28px';
      closeBtn.style.borderRadius = '12px';
      closeBtn.style.border = 'none';
      closeBtn.style.background = 'linear-gradient(135deg, #5df2c2, #29c996)';
      closeBtn.style.color = '#041810';
      closeBtn.style.fontWeight = '900';
      closeBtn.style.cursor = 'pointer';
      closeBtn.onclick = () => overlay.remove();
      overlay.appendChild(closeBtn);

      document.body.appendChild(overlay);
  }

  function openStarrDrop() {
      if (playerData.starrDrops <= 0) return;
      playerData.starrDrops--;
      saveProgress();

      const rarities = [
          { name: 'Rare', color: '#5df2c2', coinMin: 15, coinMax: 30 },
          { name: 'Super Rare', color: '#00aaff', coinMin: 40, coinMax: 80 },
          { name: 'Epic', color: '#ccaaff', coinMin: 100, coinMax: 200 },
          { name: 'Mythic', color: '#ff6b6b', coinMin: 250, coinMax: 400 },
          { name: 'Legendary', color: '#ffd700', coinMin: 500, coinMax: 1000 },
          { name: 'Ultra', color: '#ff00ff', coinMin: 1500, coinMax: 2500 }
      ];
      let taps = 0;
      const maxTaps = 4;
      let rarityScore = 0;
      let rewardRevealed = false;

      const overlay = document.createElement('div');
      overlay.style.cssText = 'position:fixed;inset:0;background:radial-gradient(circle at 50% 32%,rgba(46,26,92,0.94),rgba(2,4,16,0.98));z-index:1000;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:sans-serif;user-select:none;touch-action:manipulation;';

      const header = document.createElement('div');
      header.textContent = 'TAPPER UPPER';
      header.style.cssText = 'font-size:15px;font-weight:900;letter-spacing:0.35em;color:#9fd8ff;opacity:0.9;';
      overlay.appendChild(header);

      const banner = document.createElement('div');
      banner.textContent = rarities[0].name.toUpperCase();
      banner.style.cssText = 'margin-top:14px;padding:8px 26px;border-radius:999px;font-size:30px;font-weight:900;color:#04121a;background:' + rarities[0].color + ';box-shadow:0 0 34px ' + rarities[0].color + ';transition:all 0.25s;';
      overlay.appendChild(banner);

      const orb = document.createElement('div');
      orb.textContent = '\u2B50';
      orb.style.cssText = 'margin-top:30px;width:168px;height:168px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:76px;background:radial-gradient(circle at 35% 30%,#ffffff88,' + rarities[0].color + ' 55%,#00000055);box-shadow:0 0 60px ' + rarities[0].color + ',inset 0 -18px 34px rgba(0,0,0,0.35);transition:all 0.18s;';
      overlay.appendChild(orb);

      const pips = document.createElement('div');
      pips.style.cssText = 'display:flex;gap:10px;margin-top:28px;';
      const pipEls = [];
      for (let p = 0; p < maxTaps; p++) {
          const pip = document.createElement('div');
          pip.style.cssText = 'width:16px;height:16px;border-radius:50%;background:#2c3e55;border:2px solid #5d7ea6;transition:all 0.2s;';
          pips.appendChild(pip); pipEls.push(pip);
      }
      overlay.appendChild(pips);

      const instruction = document.createElement('p');
      instruction.textContent = 'TAP THE ORB!';
      instruction.style.cssText = 'font-size:22px;font-weight:800;margin-top:18px;animation:pulse 1s infinite alternate;';
      overlay.appendChild(instruction);

      if (!document.getElementById('pulse-style')) {
        const style = document.createElement('style');
        style.id = 'pulse-style';
        style.innerHTML = `@keyframes pulse { from { opacity: 0.5; transform: scale(0.95); } to { opacity: 1; transform: scale(1.05); } }`;
        document.head.appendChild(style);
      }
      document.body.appendChild(overlay);

      const paintOrb = () => {
          const c = rarities[rarityScore].color;
          banner.textContent = rarities[rarityScore].name.toUpperCase();
          banner.style.background = c; banner.style.boxShadow = '0 0 34px ' + c;
          orb.style.background = 'radial-gradient(circle at 35% 30%,#ffffff88,' + c + ' 55%,#00000055)';
          orb.style.boxShadow = '0 0 60px ' + c + ',inset 0 -18px 34px rgba(0,0,0,0.35)';
          orb.style.transform = 'scale(1.15)';
          setTimeout(() => orb.style.transform = 'scale(1)', 110);
          pipEls.forEach((pip, idx) => {
              pip.style.background = idx < taps ? c : '#2c3e55';
              pip.style.boxShadow = idx < taps ? '0 0 12px ' + c : 'none';
          });
      };

      const handleTap = () => {
          if (rewardRevealed) { overlay.remove(); return; }
          if (taps >= maxTaps) {
              const rInfo = rarities[rarityScore];
              const rewardCoins = Math.floor(Math.random() * (rInfo.coinMax - rInfo.coinMin + 1)) + rInfo.coinMin;
              const gemReward = Math.max(1, Math.floor(rewardCoins / 400));
              const soulReward = rollSoulReward(8, 18);
              const tapperCorePieces = Math.random() < 0.15 ? (2 + Math.floor(Math.random() * 9)) : 0;
              if (tapperCorePieces) addCorePieces(tapperCorePieces);
              const tapperSkinDrop = rollTapperSkinDrop(0.02);
              playerData.coins += rewardCoins;
              playerData.gems += gemReward;
              addSouls(soulReward);
              saveProgress();
              if (typeof refreshBrawlerList === 'function') refreshBrawlerList();
              rewardRevealed = true;
              orb.textContent = '\uD83C\uDF81';
              const splash = document.createElement('div'); splash.style.display='flex'; splash.style.flexDirection='column'; splash.style.alignItems='center';
              const coinsGroup = document.createElement('div'); coinsGroup.style.position='relative'; coinsGroup.style.width='280px'; coinsGroup.style.height='120px';
              splash.appendChild(coinsGroup);
              const coinsN = Math.min(10, Math.max(3, Math.floor(rewardCoins/80)));
              for(let j=0;j<coinsN;j++){
                  const el = document.createElement('div'); el.style.position='absolute'; el.style.width='28px'; el.style.height='28px'; el.style.borderRadius='50%';
                  el.style.background='linear-gradient(180deg,#ffd766,#ffb300)'; el.style.left='50%'; el.style.top='50%'; el.style.transform='translate(-50%,-50%) scale(0.6)'; el.style.opacity='0'; el.style.boxShadow='0 6px 12px rgba(0,0,0,0.25)';
                  coinsGroup.appendChild(el);
                  (function(e2,idx){ setTimeout(()=>{ e2.style.transition='all 550ms cubic-bezier(.2,.9,.3,1)'; const ang=(Math.PI*2)*(idx/coinsN)+(Math.random()-0.5); const dist=60+Math.random()*80; e2.style.transform=`translate(${Math.cos(ang)*dist}px, ${Math.sin(ang)*dist}px) scale(1)`; e2.style.opacity='1'; }, idx*50); })(el,j);
              }
              const tot = document.createElement('div'); tot.textContent = `+${rewardCoins} COINS! +${gemReward} GEMS! +${soulReward} SOULS!`; tot.style.color='#ffd700'; tot.style.fontSize='34px'; tot.style.fontWeight='900'; tot.style.marginTop='10px'; tot.style.textShadow='0 0 20px #ffd700';
              splash.appendChild(tot);
              if (tapperCorePieces) {
                  const cpLine = document.createElement('div');
                  cpLine.textContent = `+${tapperCorePieces} CORE PIECES!`;
                  cpLine.style.cssText = 'color:#59f2d6;font-size:24px;font-weight:900;margin-top:8px;text-shadow:0 0 16px #59f2d6';
                  splash.appendChild(cpLine);
              }
              if (tapperSkinDrop) {
                  const skinLine = document.createElement('div');
                  skinLine.textContent = tapperSkinDrop.fallback ? tapperSkinDrop.name : `🎁 SKIN DROP: ${tapperSkinDrop.name} (${tapperSkinDrop.brawlerName})!`;
                  skinLine.style.cssText = 'color:#ff9ff3;font-size:24px;font-weight:900;margin-top:8px;text-shadow:0 0 16px #ff9ff3';
                  splash.appendChild(skinLine);
              }
              overlay.appendChild(splash);
              instruction.textContent = 'TAP ANYWHERE TO CLOSE'; instruction.style.animation='none';
              return;
          }
          taps++;
          if (Math.random() < 0.48) {
              rarityScore = Math.min(rarityScore + 1, rarities.length - 1);
          }
          paintOrb();
          if (taps >= maxTaps) instruction.textContent = 'TAP TO REVEAL REWARD!';
      };
      overlay.onpointerdown = (event) => { event.preventDefault(); handleTap(); };
  }

  function openSuperStarrDrop() {
      if (!playerData.superTapperCount || playerData.superTapperCount <= 0) return;
      playerData.superTapperCount = Math.max(0, playerData.superTapperCount - 1);
      saveProgress();
      if (typeof refreshBrawlerList === 'function') refreshBrawlerList();

      const rarities = [
          { name: 'Rare', color: '#5df2c2', coinMin: 50, coinMax: 80 },
          { name: 'Super Rare', color: '#00aaff', coinMin: 100, coinMax: 160 },
          { name: 'Epic', color: '#ccaaff', coinMin: 200, coinMax: 350 },
          { name: 'Mythic', color: '#ff6b6b', coinMin: 400, coinMax: 700 },
          { name: 'Legendary', color: '#ffd700', coinMin: 800, coinMax: 1500 },
          { name: 'Ultra', color: '#ff00ff', coinMin: 2000, coinMax: 3500 }
      ];
      function pickWeighted() {
          const r = Math.random() * 100;
          if (r < 3) return rarities[5];
          if (r < 12) return rarities[4];
          if (r < 30) return rarities[3];
          if (r < 55) return rarities[2];
          if (r < 80) return rarities[1];
          return rarities[0];
      }
      // Chaos is decided up front, revealed by tapping: the drop splits
      // into 2..8 mini-drops, each holding one weighted reward roll.
      const splits = Math.floor(Math.random() * 7) + 2;
      const rolls = [];
      for (let k = 0; k < splits; k++) {
          const choice = pickWeighted();
          rolls.push({ rarity: choice, coin: Math.floor(Math.random() * (choice.coinMax - choice.coinMin + 1)) + choice.coinMin, core: Math.random() < 0.15 ? (2 + Math.floor(Math.random() * 4)) : 0 });
      }
      const superSkinDrop = rollTapperSkinDrop(0.04);
      let orbCount = 1;
      let revealed = false;

      const overlay = document.createElement('div');
      overlay.style.cssText = 'position:fixed;inset:0;background:radial-gradient(circle at 50% 30%,rgba(120,8,140,0.95),rgba(8,0,18,0.99));z-index:1000;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:sans-serif;user-select:none;touch-action:manipulation;';
      const title = document.createElement('h1');
      title.textContent = '\u2726 SUPER TAPPER: CHAOS \u2726';
      title.style.cssText = 'font-size:40px;color:#ff00ff;text-shadow:0 0 34px #ff00ff;margin:0;text-align:center;';
      overlay.appendChild(title);
      const info = document.createElement('p');
      info.textContent = 'Odds per split: Rare 20% / Super Rare 25% / Epic 25% / Mythic 18% / Legendary 9% / Ultra 3%';
      info.style.cssText = 'margin-top:10px;font-size:15px;color:#f3c6ff;opacity:0.9;text-align:center;padding:0 16px;';
      overlay.appendChild(info);
      const stage = document.createElement('div');
      stage.style.cssText = 'display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:center;max-width:560px;min-height:190px;margin-top:16px;padding:0 12px;';
      overlay.appendChild(stage);
      const feed = document.createElement('div');
      feed.style.cssText = 'display:flex;flex-direction:column;align-items:center;min-height:30px;';
      overlay.appendChild(feed);
      const instruction = document.createElement('p');
      instruction.textContent = 'TAP TO SPLIT THE CHAOS!';
      instruction.style.cssText = 'font-size:22px;font-weight:800;margin-top:14px;animation:pulse 1s infinite alternate;';
      overlay.appendChild(instruction);
      document.body.appendChild(overlay);

      const paintOrbs = (popLast) => {
          stage.innerHTML = '';
          const size = orbCount <= 1 ? 168 : orbCount <= 3 ? 118 : orbCount <= 5 ? 92 : 74;
          for (let k = 0; k < orbCount; k++) {
              const held = rolls[Math.min(k, rolls.length - 1)];
              const orb = document.createElement('div');
              orb.textContent = '\u2726';
              orb.style.cssText = `width:${size}px;height:${size}px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:${Math.round(size * 0.42)}px;color:#fff;background:radial-gradient(circle at 35% 30%,#ffffff77,${held.rarity.color} 58%,#00000066);box-shadow:0 0 ${Math.round(size * 0.36)}px ${held.rarity.color},inset 0 -14px 26px rgba(0,0,0,0.4);transition:all 0.18s;`;
              if (popLast && k === orbCount - 1) { orb.style.transform = 'scale(1.3)'; setTimeout(() => orb.style.transform = 'scale(1)', 130); }
              stage.appendChild(orb);
          }
      };
      paintOrbs(false);

      const revealAll = () => {
          revealed = true;
          stage.innerHTML = '';
          let total = 0;
          rolls.forEach((roll, idx) => {
              total += roll.coin;
              const chip = document.createElement('div');
              chip.textContent = `${roll.rarity.name}: +${roll.coin}`;
              chip.style.cssText = `margin-top:6px;padding:5px 16px;border-radius:999px;font-weight:900;font-size:17px;color:#0b0614;background:${roll.rarity.color};box-shadow:0 0 16px ${roll.rarity.color};opacity:0;transform:scale(0.7);transition:all 0.25s;`;
              feed.appendChild(chip);
              setTimeout(() => { chip.style.opacity = '1'; chip.style.transform = 'scale(1)'; }, 110 * idx);
          });
          const gemReward = Math.max(2, Math.floor(total / 250));
          const soulReward = rollSoulReward(20, 40);
          const coreTotal = rolls.reduce((sum, roll) => sum + (roll.core || 0), 0);
          if (coreTotal) addCorePieces(coreTotal);
          setTimeout(() => {
              const totalTxt = document.createElement('h2');
              totalTxt.textContent = `+${total} COINS! +${gemReward} GEMS! +${soulReward} SOULS!` + (coreTotal ? ` +${coreTotal} CORE PIECES!` : '');
              totalTxt.style.cssText = 'color:#ffd700;text-shadow:0 0 20px #ffd700;margin:12px 0 0;';
              feed.appendChild(totalTxt);
              if (superSkinDrop) {
                  const skinTxt = document.createElement('div');
                  skinTxt.textContent = superSkinDrop.fallback ? superSkinDrop.name : `🎁 SKIN DROP: ${superSkinDrop.name} (${superSkinDrop.brawlerName})!`;
                  skinTxt.style.cssText = 'color:#ff9ff3;font-size:22px;font-weight:900;margin-top:6px;text-shadow:0 0 16px #ff9ff3;';
                  feed.appendChild(skinTxt);
              }
              instruction.textContent = 'TAP ANYWHERE TO CLOSE';
              instruction.style.animation = 'none';
          }, 110 * rolls.length + 60);
          playerData.gems += gemReward;
          addSouls(soulReward);
          playerData.coins += total;
          saveProgress();
          if (typeof refreshBrawlerList === 'function') refreshBrawlerList();
      };

      const handleTap = () => {
          if (revealed) { overlay.remove(); return; }
          if (orbCount < splits) {
              orbCount++;
              paintOrbs(true);
              instruction.textContent = orbCount >= splits ? 'CHAOS COMPLETE \u2014 TAP TO CRACK THEM ALL OPEN!' : `IT SPLIT! \u00d7${orbCount} \u2014 TAP TO SPLIT AGAIN!`;
              return;
          }
          revealAll();
      };
      overlay.onpointerdown = (event) => { event.preventDefault(); handleTap(); };
  }

  function openHyperStarrDrop() {
      if (!playerData.hyperTapperCount || playerData.hyperTapperCount <= 0) return;
      playerData.hyperTapperCount = Math.max(0, playerData.hyperTapperCount - 1);
      saveProgress();
      if (typeof refreshBrawlerList === 'function') refreshBrawlerList();

      const overlay = document.createElement('div');
      overlay.style.position = 'fixed'; overlay.style.inset = '0';
      overlay.style.background = 'radial-gradient(circle at 50% 30%, rgba(8,80,90,0.97), rgba(2,10,16,0.99))'; overlay.style.zIndex = '1000';
      overlay.style.display = 'flex'; overlay.style.flexDirection = 'column';
      overlay.style.alignItems = 'center'; overlay.style.justifyContent = 'center';
      overlay.style.color = '#fff'; overlay.style.fontFamily = 'sans-serif'; overlay.style.userSelect = 'none';
      overlay.style.fontWeight = 'bold';

      const title = document.createElement('h1');
      title.textContent = '⚡ SURGE TAPPER ⚡';
      title.style.fontSize = '52px'; title.style.color = '#59f2d6'; title.style.textShadow = '0 0 40px #59f2d6';
      title.style.marginBottom = '24px'; title.style.animation = 'pulse 1s infinite';
      overlay.appendChild(title);

      const infoText = document.createElement('p');
    infoText.textContent = 'TAP TO REVEAL YOUR CORE SURGE! (65% Core Surge unlock / 35% Core Pieces overflow)';
      infoText.style.fontSize = '24px'; infoText.style.marginBottom = '36px'; infoText.style.color = '#aef';
      overlay.appendChild(infoText);

      let tapped = false;
      overlay.onclick = (e) => {
          if (tapped) { document.body.removeChild(overlay); return; }
          tapped = true;
          e.preventDefault();
          
          // 65% chance: free hypercharge, 35% chance: 1k coins
          const isHyper = Math.random() < 0.65;
          
          // Clear existing text
          infoText.remove();
          
          const resultDiv = document.createElement('div');
          resultDiv.style.fontSize = '32px'; resultDiv.style.marginTop = '36px';
          resultDiv.style.textAlign = 'center'; resultDiv.style.lineHeight = '1.5';
          const soulReward = rollSoulReward(45, 80);
          addSouls(soulReward);
          
          if (isHyper) {
              // Grant a random locked hypercharge permanently (outside-match reward).
              const lockedHyperBrawlers = allBrawlers.filter((bid) => {
                  const prog = getOrCreateProgress(bid);
                  const isDisabled = (brawlerData && brawlerData[bid] && brawlerData[bid].disabled) || disabledBrawlers.has(bid);
                  return !isDisabled && !prog.hyperchargeUnlocked;
              });
              if (lockedHyperBrawlers.length > 0) {
                  const chosenId = lockedHyperBrawlers[Math.floor(Math.random() * lockedHyperBrawlers.length)];
                  const chosenProg = getOrCreateProgress(chosenId);
                  chosenProg.hyperchargeUnlocked = true;
                  playerData.gems += 8;
                  if (selectedBrawler === chosenId) updateHyperButton();
                  const chosenName = (brawlerData[chosenId] && brawlerData[chosenId].name) || chosenId;
                  resultDiv.innerHTML = `✨ CORE SURGE UNLOCKED! ✨<br><span style="font-size: 20px; color: #59f2d6; margin-top: 12px; display: block;">${chosenName}'s Core Surge is now unlocked! +8 GEMS! +${soulReward} SOULS!</span>`;
                  resultDiv.style.color = '#e0f';
                  resultDiv.style.textShadow = '0 0 20px #e0f';
              } else {
                  // All Core Surges unlocked: the surge overflows into Core Pieces.
                  addCorePieces(60);
                  playerData.gems += 8;
                  resultDiv.innerHTML = `✨ ALL CORE SURGES ALREADY UNLOCKED! ✨<br><span style="font-size: 20px; color: #59f2d6; margin-top: 12px; display: block;">Surge overflow: +60 CORE PIECES and +8 GEMS. +${soulReward} SOULS!</span>`;
                  resultDiv.style.color = '#ffd700';
                  resultDiv.style.textShadow = '0 0 20px #ffd700';
              }
          } else {
              // Surge overflow: Core Pieces instead of a surge unlock.
              addCorePieces(60);
              playerData.gems += 8;
              resultDiv.innerHTML = `💠 SURGE OVERFLOW: +60 CORE PIECES! 💠<br><span style="font-size: 20px; color: #59f2d6; margin-top: 12px; display: block;">The surge had nowhere to go! +8 GEMS! +${soulReward} SOULS!</span>`;
              resultDiv.style.color = '#ffd700';
              resultDiv.style.textShadow = '0 0 20px #ffd700';
          }
          
          overlay.appendChild(resultDiv);
          const closeMsg = document.createElement('p');
          closeMsg.textContent = 'TAP ANYWHERE TO CLOSE';
          closeMsg.style.fontSize = '16px'; closeMsg.style.marginTop = '48px'; closeMsg.style.color = '#aaf'; closeMsg.style.opacity = '0.7';
          overlay.appendChild(closeMsg);
          saveProgress();
          if (typeof refreshBrawlerList === 'function') refreshBrawlerList();
      };
      
      // Add CSS animation for pulse effect
      if (!document.getElementById('hyperTapperPulse')) {
          const style = document.createElement('style');
          style.id = 'hyperTapperPulse';
          style.textContent = '@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.8; transform: scale(1.05); } }';
          document.head.appendChild(style);
      }
      
      document.body.appendChild(overlay);
  }

  // Helper to open either UI from new DOM buttons
  function openStarrDropUI(isSuper) {
      if (isSuper) return openSuperStarrDrop();
      return openStarrDrop();
  }

  // ===== Season 4 Arenaaween: Spooky Boxes =====
  const ARENAAWEEN_SKIN_IDS = ['pumpkin-king', 'count-cursed', 'phantom-copyphase', 'reaper-darkener', 'nightmare-awakenator', 'jack-o-demon'];
  const XPLODEMIS_SKIN_IDS = ['xploder-rocketeer','krampus-darkener','frostbite-feathers','tinsel-looma','nutcracker-outlit','gingerbread-cheeseburger'];
  function unownedXplodemisSkins() {
      if (!playerData.ownedSkins) playerData.ownedSkins = {};
      return XPLODEMIS_SKIN_IDS.filter(id => {
          const skin = skinsDatabase[id];
          return skin && !(playerData.ownedSkins[skin.brawler] || []).includes(id);
      });
  }
  function unownedArenaweenSkins() {
      if (!playerData.ownedSkins) playerData.ownedSkins = {};
      return ARENAAWEEN_SKIN_IDS.filter(id => {
          const skin = skinsDatabase[id];
          return skin && !(playerData.ownedSkins[skin.brawler] || []).includes(id);
      });
  }
  function openSpookyBox() {
      if (!playerData.spookyBoxCount || playerData.spookyBoxCount <= 0) return;
      playerData.spookyBoxCount--;
      saveProgress();
      const overlay = document.createElement('div');
      overlay.style.cssText = 'position:fixed;inset:0;background:radial-gradient(circle at 50% 35%,rgba(94,24,140,0.92),rgba(5,2,12,0.98));z-index:1000;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:sans-serif;user-select:none;touch-action:manipulation;';
      const title = document.createElement('h1');
      title.textContent = '🎃 SPOOKY BOX 🎃';
      title.style.cssText = 'font-size:44px;color:#ff8c1a;text-shadow:0 0 30px #ff8c1a;margin:0;';
      overlay.appendChild(title);
      const box = document.createElement('div');
      box.textContent = '🎁';
      box.style.cssText = 'font-size:120px;margin:26px 0;filter:drop-shadow(0 0 34px rgba(255,140,26,0.8));animation:pulse 1s infinite alternate;';
      overlay.appendChild(box);
      const instruction = document.createElement('p');
      instruction.textContent = 'TAP THE BOX... IF YOU DARE';
      instruction.style.cssText = 'font-size:22px;color:#e6ccff;';
      overlay.appendChild(instruction);
      const odds = document.createElement('p');
      odds.textContent = 'Inside: a chance at 6 Arenaaween skins, Coins, or Souls';
      odds.style.cssText = 'font-size:15px;color:#bfa3e0;opacity:0.85;';
      overlay.appendChild(odds);
      document.body.appendChild(overlay);
      let revealed = false;
      const reveal = () => {
          if (revealed) { overlay.remove(); if (typeof refreshBrawlerList === 'function') refreshBrawlerList(); return; }
          revealed = true;
          box.style.animation = 'none'; box.style.transform = 'scale(1.25) rotate(-6deg)';
          const result = document.createElement('div');
          result.style.cssText = 'text-align:center;margin-top:10px;max-width:520px;padding:0 18px;';
          const unowned = unownedArenaweenSkins();
          const roll = Math.random();
          if (unowned.length > 0 && roll < 0.30) {
              const skinId = unowned[Math.floor(Math.random() * unowned.length)];
              const skin = skinsDatabase[skinId];
              if (!playerData.ownedSkins[skin.brawler]) playerData.ownedSkins[skin.brawler] = [];
              playerData.ownedSkins[skin.brawler].push(skin.id);
              if (!playerData.selectedSkins) playerData.selectedSkins = {};
              playerData.selectedSkins[skin.brawler] = skin.id;
              result.innerHTML = `<div style="font-size:84px">${skin.icon || '🎃'}</div><div style="font-size:34px;font-weight:900;color:${skin._displayColor || '#ff8c1a'};text-shadow:0 0 22px ${skin._displayColor || '#ff8c1a'}">${skin.name}</div><div style="font-size:18px;color:#e6ccff;margin-top:6px">NEW SKIN for ${(brawlerData[skin.brawler] && brawlerData[skin.brawler].name) || skin.brawler} — auto-equipped!</div>`;
          } else if (roll < 0.75) {
              const coins = 300 + Math.floor(Math.random() * 601);
              playerData.coins = (playerData.coins || 0) + coins + (unowned.length === 0 && roll < 0.30 ? 1200 : 0);
              const jackpot = unowned.length === 0 && roll < 0.30;
              result.innerHTML = `<div style="font-size:84px">💰</div><div style="font-size:34px;font-weight:900;color:#ffd700;text-shadow:0 0 22px #ffd700">+${(coins + (jackpot ? 1200 : 0)).toLocaleString()} COINS!</div>${jackpot ? '<div style="font-size:16px;color:#e6ccff;margin-top:6px">Full Arenaaween collection jackpot!</div>' : ''}`;
          } else {
              const souls = 40 + Math.floor(Math.random() * 81);
              if (typeof addSouls === 'function') addSouls(souls); else playerData.souls = (playerData.souls || 0) + souls;
              result.innerHTML = `<div style="font-size:84px">👻</div><div style="font-size:34px;font-weight:900;color:#c792ff;text-shadow:0 0 22px #8e44ad">+${souls} SOULS!</div>`;
          }
          overlay.appendChild(result);
          instruction.textContent = playerData.spookyBoxCount > 0 ? `TAP TO CLOSE • ${playerData.spookyBoxCount} Spooky Box${playerData.spookyBoxCount === 1 ? '' : 'es'} left` : 'TAP ANYWHERE TO CLOSE';
          saveProgress();
      };
      overlay.onpointerdown = (event) => { event.preventDefault(); reveal(); };
  }

  function openPresent() {
      if (!playerData.presentCount || playerData.presentCount <= 0) return;
      playerData.presentCount--;
      saveProgress();
      const overlay = document.createElement('div');
      overlay.style.cssText = 'position:fixed;inset:0;background:radial-gradient(circle at 50% 35%,rgba(20,90,60,0.94),rgba(4,10,6,0.98));z-index:1000;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:sans-serif;user-select:none;touch-action:manipulation;';
      const title = document.createElement('h1');
      title.textContent = '🎁 PRESENT 🎁';
      title.style.cssText = 'font-size:44px;color:#ffd76b;text-shadow:0 0 30px #ffd76b;margin:0;';
      overlay.appendChild(title);
      const box = document.createElement('div');
      box.textContent = '🎁';
      box.style.cssText = 'font-size:120px;margin:26px 0;filter:drop-shadow(0 0 34px rgba(255,215,107,0.8));animation:pulse 1s infinite alternate;';
      overlay.appendChild(box);
      const instruction = document.createElement('p');
      instruction.textContent = 'TAP TO UNWRAP!';
      instruction.style.cssText = 'font-size:22px;color:#ffe9b8;';
      overlay.appendChild(instruction);
      const odds = document.createElement('p');
      odds.textContent = 'Every Present holds 1-4 rewards: a shot at 6 Xplodemis skins, Coins, Souls, Gems or Core Pieces';
      odds.style.cssText = 'font-size:15px;color:#bfe8cf;opacity:0.85;text-align:center;padding:0 18px;';
      overlay.appendChild(odds);
      document.body.appendChild(overlay);
      let revealed = false;
      const reveal = () => {
          if (revealed) { overlay.remove(); if (typeof refreshBrawlerList === 'function') refreshBrawlerList(); return; }
          revealed = true;
          box.style.animation = 'none'; box.style.transform = 'scale(1.25) rotate(5deg)';
          const result = document.createElement('div');
          result.style.cssText = 'text-align:center;margin-top:10px;max-width:540px;padding:0 18px;';
          // Reward count: 1 (45%) / 2 (35%) / 3 (15%) / 4 (5%)
          const countRoll = Math.random();
          const rewardCount = countRoll < 0.45 ? 1 : countRoll < 0.80 ? 2 : countRoll < 0.95 ? 3 : 4;
          const lines = [];
          const unowned = unownedXplodemisSkins();
          let skinAwarded = false;
          if (Math.random() < 0.25) {
              if (unowned.length > 0) {
                  const skinId = unowned[Math.floor(Math.random() * unowned.length)];
                  const skin = skinsDatabase[skinId];
                  if (!playerData.ownedSkins[skin.brawler]) playerData.ownedSkins[skin.brawler] = [];
                  playerData.ownedSkins[skin.brawler].push(skin.id);
                  if (!playerData.selectedSkins) playerData.selectedSkins = {};
                  playerData.selectedSkins[skin.brawler] = skin.id;
                  lines.push(`<div style="font-size:64px">${skin.icon || '🎁'}</div><div style="font-size:32px;font-weight:900;color:${skin._displayColor || '#ffd76b'};text-shadow:0 0 22px ${skin._displayColor || '#ffd76b'}">${skin.name}</div><div style="font-size:16px;color:#ffe9b8">NEW SKIN for ${(brawlerData[skin.brawler] && brawlerData[skin.brawler].name) || skin.brawler} — auto-equipped!</div>`);
                  skinAwarded = true;
              } else {
                  playerData.coins = (playerData.coins || 0) + 1200;
                  lines.push('<div style="font-size:26px;font-weight:900;color:#ffd700">+1,200 COINS — full Xplodemis collection jackpot!</div>');
                  skinAwarded = true; // jackpot consumes the skin slot
              }
          }
          const fillerCount = rewardCount - (skinAwarded ? 1 : 0);
          for (let i = 0; i < fillerCount; i++) {
              const r = Math.random();
              if (r < 0.40) {
                  const coins = 300 + Math.floor(Math.random() * 601);
                  playerData.coins = (playerData.coins || 0) + coins;
                  lines.push(`<div style="font-size:24px;font-weight:900;color:#ffd700">💰 +${coins.toLocaleString()} COINS</div>`);
              } else if (r < 0.65) {
                  const souls = 40 + Math.floor(Math.random() * 81);
                  if (typeof addSouls === 'function') addSouls(souls); else playerData.souls = (playerData.souls || 0) + souls;
                  lines.push(`<div style="font-size:24px;font-weight:900;color:#c792ff">👻 +${souls} SOULS</div>`);
              } else if (r < 0.85) {
                  const gems = 5 + Math.floor(Math.random() * 11);
                  playerData.gems = (playerData.gems || 0) + gems;
                  lines.push(`<div style="font-size:24px;font-weight:900;color:#6ee7ff">💎 +${gems} GEMS</div>`);
              } else {
                  const corePieces = 3 + Math.floor(Math.random() * 6);
                  addCorePieces(corePieces);
                  lines.push(`<div style="font-size:24px;font-weight:900;color:#59f2d6">💠 +${corePieces} CORE PIECES</div>`);
              }
          }
          result.innerHTML = `<div style="font-size:17px;color:#ffe9b8;margin-bottom:8px">${rewardCount} REWARD${rewardCount > 1 ? 'S' : ''} INSIDE!</div>` + lines.join('');
          overlay.appendChild(result);
          instruction.textContent = playerData.presentCount > 0 ? `TAP TO CLOSE • ${playerData.presentCount} Present${playerData.presentCount === 1 ? '' : 's'} left` : 'TAP ANYWHERE TO CLOSE';
          saveProgress();
      };
      overlay.onpointerdown = (event) => { event.preventDefault(); reveal(); };
  }

  function sanitizeSummonerPlanEntry(plan) {
      if (!plan || typeof plan !== 'object') return null;
      const type = plan.type === 'choice' ? 'choice' : 'single';
      const rarity = typeof plan.rarity === 'string' ? plan.rarity : 'Common';
      const options = Array.isArray(plan.options) ? plan.options : [];
      const cleanOptions = [...new Set(options.filter((bid) => typeof bid === 'string' && allBrawlers.includes(bid) && bid !== 'outlit'))]
          .filter((bid) => !isBrawlerUnlocked(bid) && !disabledBrawlers.has(bid));
      if (type === 'choice' && cleanOptions.length < 2) return null;
      if (type === 'single' && cleanOptions.length < 1) return null;
      return {
          type,
          rarity,
          cost: getSoulUnlockCostForRarity(rarity),
          options: type === 'choice' ? cleanOptions.slice(0, 2) : [cleanOptions[0]],
          fromDeferred: !!plan.fromDeferred
      };
  }

  
