        for(let i=0;i<3;i++){const a=i*Math.PI*2/3;explosions.push({x:owner.x+Math.cos(a)*36,y:owner.y+Math.sin(a)*36,radius:34,life:0,maxLife:.28,color:hyper?'rgba(220,55,255,.8)':'rgba(210,45,70,.75)'});}
