                ownerBrawler: 'kage',
                isKageGiantStar: true,
                superActivationId: superActivationId,
                x: owner.x + Math.cos(starAng) * (owner.radius + 12),
                y: owner.y + Math.sin(starAng) * (owner.radius + 12),
                vx: Math.cos(starAng) * speed,
                vy: Math.sin(starAng) * speed,
