        panel.style.border = '2px solid rgba(255, 211, 117, 0.45)';
        panel.style.boxShadow = '0 0 40px rgba(0,0,0,0.85), 0 0 20px rgba(255, 211, 117, 0.15)';
        panel.style.borderRadius = '16px';
