  window.addEventListener('keydown', (e)=>{
    const k = e.key.toLowerCase();
    if (k === 'escape' && aimingSuper) { e.preventDefault(); cancelSuperAim(); return; }
    const prog = getSelectedProgress();
        const gadgetUnlocked = isTraining || !!prog.gadgetUnlocked;
        const spUnlocked = isTraining || !!prog.starPowerUnlocked;
        const hcUnlocked = isTraining || !!prog.hyperchargeUnlocked;
    
        if(k === 'q' && gadgetUnlocked){
            if (isTutorialMode) tutorialProgress.gadget = true;
            gadgetBtn.click();
        }
    if(k === 'r'){
        activateSignatureAbility(player);
    }
    if(k === 'e' || ((k === ' ' || k === 'escape' || k === 'x') && player.blinkeyeSteering && player.blinkeyeActiveEye)){
        if (isTutorialMode) tutorialProgress.super = true;
        startAimingSuper();
    }
        if(k === 'f' && hcUnlocked){
            if (isTutorialMode) tutorialProgress.hyper = true;
            activateHypercharge();
        }
    
        if(spUnlocked) {
        if(k === '1'){ const s = document.querySelector('input[name="star"][value="slow"]'); if(s) { s.checked = true; selectedStar = 'slow'; } }
        if(k === '2'){ const s = document.querySelector('input[name="star"][value="long"]'); if(s) { s.checked = true; selectedStar = 'long'; } }
    }
    
    if(k === 'enter'){ if(startBtn) startBtn.click(); }
  });

