              const livePool = typeof aliveBots !== 'undefined' ? aliveBots : bots;
              const candidates = [player, ...livePool].filter(c => c && c.hp > 0 && c.id !== b.ownerId && (!fireOwner || !areAlliedEntities(fireOwner, c)));
              let closest = null, closestDist = 800;
