          ctx.translate(b.x, b.y);
          ctx.rotate(Math.atan2(b.vy, b.vx));
          ctx.fillStyle = '#f39c12';
          ctx.beginPath();
          ctx.moveTo(14, 0);
          ctx.lineTo(-10, -5);
          ctx.lineTo(-6, 0);
          ctx.lineTo(-10, 5);
