          // Dynamic radius expansion during travel (especially in hypercharge)
          const baseR = b.radius || b.baseRadius || 28;
          const cr = b.isHyper ? baseR * (1 + lifePct * 1.4) : (b.g1Active ? baseR * 1.15 : baseR);

          // Outer sonic glow
