          waveGrad.addColorStop(0.5, b.g1Active ? 'rgba(216, 115, 255, 0.65)' : 'rgba(126, 34, 206, 0.55)');
          waveGrad.addColorStop(1, 'rgba(46, 16, 101, 0)');
