          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2.5 * sz;
          ctx.beginPath();
          ctx.moveTo(-22 * sz, 0);
          ctx.lineTo(-13 * sz, -6 * sz);
          ctx.lineTo(-2 * sz, 5 * sz);
          ctx.lineTo(9 * sz, -5 * sz);
          ctx.lineTo(22 * sz, 0);
