          const range = b.range || 220;

          // Glowing sweeping blade crescent trail
          ctx.strokeStyle = b.hyperVisual ? 'rgba(255, 60, 110, 0.85)' : (b.isHeft ? 'rgba(255, 159, 67, 0.95)' : 'rgba(231, 76, 60, 0.85)');
