        const bannerW = 460;
        ctx.fillStyle = 'rgba(32, 16, 4, 0.85)';
        ctx.fillRect(innerWidth / 2 - bannerW / 2, 78, bannerW, 36);
        ctx.strokeStyle = 'rgba(255, 179, 71, 0.8)';
